var QUESTOES_FORMACAOPALAVRAS = [{"id":325,"enunciado":"Esta questão avalia conhecimentos sobre diferentes itens do conteúdo previsto para a prova. Assinale a alternativa que traz a informação correta sobre o respectivo item.","opcoes":["Os substantivos “encontro” (2º parágrafo), “absolvição” (5º parágrafo) e “necrotério” (6º parágrafo) são formados, respectivamente, por derivação imprópria, parassíntese e derivação sufixal.","O uso do vocábulo “nosso”, em “um laudo nosso” (5º parágrafo), produz um efeito de coletividade, coerente com o propósito global do texto.","A palavra “necropsia” deveria estar graficamente acentuada (“necrópsia”), pois é paroxítona terminada em ditongo.","A forma verbal “têm” não poderia estar graficamente acentuada, pois não se usam mais os acentos diferenciais.","As palavras “efetivo” e “Penitenciária” (2º parágrafo) estão empregadas como substantivos."],"correta":1,"explicacao":"Gabarito: <strong>O uso do vocábulo “nosso”, em “um laudo nosso” (5º parágrafo), produz um efeito de coletividade, coerente com o propósito global do texto.</strong>.","banca":"Fundação FAPEC","ano":2021,"temas_relacionados":["formacaoPalavras"]},{"id":458,"enunciado":"Analise os itens abaixo e assinale a alternativa correta:","opcoes":["Não há ditongo em todos os seguintes vocábulos retirados do texto: “roupas”, “pastéis, “ao”, “contribui” e “Ninguém”.","No vocábulo “crucifixo” (3º parágrafo), há dois encontros consonantais.","No 5º parágrafo, o vocábulo “coadjuvância” não constitui um neologismo na língua portuguesa.","Os vocábulos seguintes retirados do texto: “observador”, “perspicácia”, “obscenidades”, “incontrolável” e “mortal” apresentam o mesmo processo de formação de palavras.","O segmento destacado na passagem “Ser chamada de boazinha, mesmo com a melhor das intenções, é o pior dos desaforos.” (5º parágrafo) assume um valor semântico de conformidade no contexto em que aparece."],"correta":1,"explicacao":"Gabarito: <strong>No vocábulo “crucifixo” (3º parágrafo), há dois encontros consonantais.</strong>.","banca":"CONTEMAX","ano":2020,"temas_relacionados":["formacaoPalavras","encontrosConsonantais"]},{"id":469,"enunciado":"As seguintes afirmações sobre a estrutura e formação de palavras do texto são corretas, EXCETO:","opcoes":["Soterrado e terrestre são formadas por derivação e têm o mesmo radical.","Sustentáveis e autonomamente apresentam desinências formadoras de adjetivo e advérbio respectivamente.","Amontoados e inutilizável são formadas por derivação parassintética.","Garis e celestiais apresentam estruturas diferentes na formação do plural.","Atmosfera apresenta dois encontros consonantais; qualquer apresenta um ditongo e um dígrafo."],"correta":2,"explicacao":"Gabarito: <strong>Amontoados e inutilizável são formadas por derivação parassintética.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["formacaoPalavras","ditongos","digrafos","encontrosConsonantais"]},{"id":1629,"enunciado":"A menor unidade dotada de significado em uma língua é chamada de:","opcoes":["lema;","lexema;","morfema;","radical;","raiz."],"correta":2,"explicacao":"Gabarito: <strong>morfema;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2002,"enunciado":"Na oração “as desconhecidas são perigosas e potencialmente traiçoeiras”, a palavra “desconhecidas” apresenta a seguinte composição morfológica: radical “desconhec‑“, vogal temática verbal ‑i, afixo de particípio ‑d, desinência de gênero ‑a, desinência de número ‑s.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2005,"enunciado":"A palavra “bibliotecário”, usada no terceiro quadro da tira, foi formada pelo processo de","opcoes":["&#x20;erivação sufixal.","derivação prefixal.","derivação parassintética.","composição por justaposição.","composição por aglutinação."],"correta":0,"explicacao":"Gabarito: <strong>&#x20;erivação sufixal.</strong>.","banca":"FADENOR","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2006,"enunciado":"Quanto à estruturação linguística e gramatical do texto, julgue o item seguinte.\nNo trecho “da capacidade cardiorrespiratória”, a palavra “cardiorrespiratória” é formada pela junção do prefixo “cardio‑“, que significa “coração”, com o vocábulo “respiratório”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2007,"enunciado":"&#x20;A palavra “estereótipo” é formada por dois radicais gregos que significam, respectivamente:","opcoes":["Belo e Letra, respectivamente.","Sólido e Impressão, respectivamente.","Frágil e Impressão, respectivamente.","Fraco e Opinião, respectivamente.","Belo e Conceito, respectivamente."],"correta":1,"explicacao":"Gabarito: <strong>Sólido e Impressão, respectivamente.</strong>.","banca":"CEV-URCA","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2008,"enunciado":"Na palavra “reprodução”, identifica-se o seguinte processo de formação:","opcoes":["Apenas prefixal.","Apenas sufixal.","Prefixal e sufixal.","Composição por justaposição.","Composição por aglutinação."],"correta":2,"explicacao":"Gabarito: <strong>Prefixal e sufixal.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2009,"enunciado":"Algumas palavras são formadas por um processo de derivação prefixal. Neste caso, qual é o prefixo da palavra “internacional”?","opcoes":["In.","Inter.","Interna.","Nacional."],"correta":1,"explicacao":"Gabarito: <strong>Inter.</strong>.","banca":"Itame","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2011,"enunciado":"Leia este trecho e responda a seguir. “A democracia e a educação são irmãs gêmeas. Ambas fazem parte do mesmo processo civilizatório desde a Grécia antiga.” http://portal.mec.gov.br A palavra “democracia” é formada pelos radicais –demo e –cracia e significa governo do povo. Está incorreta a correspondência apresentada em:","opcoes":["Oligarquia = governo de um pequeno grupo.","Teocracia = governo de religiosos.","Aristocracia = governo dos nobres.","Plutocracia = governo exercido por plebeus."],"correta":3,"explicacao":"Gabarito: <strong>Plutocracia = governo exercido por plebeus.</strong>.","banca":"ADM\\&TEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2013,"enunciado":"Considerando a expressão \"pré-pandemia de Covid\", qual é o significado implícito do prefixo \"pré-\"?","opcoes":["Indica um evento que ocorreu simultaneamente à pandemia de Covid.","Denota um período que sucedeu imediatamente à pandemia de Covid.","Marca um momento anterior ao início da pandemia de Covid.","Refere-se a uma condição permanente, independente da pandemia de Covid."],"correta":2,"explicacao":"Gabarito: <strong>Marca um momento anterior ao início da pandemia de Covid.</strong>.","banca":"Instituto Fênix","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2014,"enunciado":"Analise as palavras apresentadas a seguir, que ocorrem no texto, quanto aos elementos mórficos que as constituem. Assinale aquela que apresenta um sufixo derivacional formador de advérbios de modo na língua portuguesa.","opcoes":["cosmológico.","extraordinário.","vizinhança.","oscilações.","uniformemente."],"correta":4,"explicacao":"Gabarito: <strong>uniformemente.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2015,"enunciado":"Analise o cartaz abaixo. 6.png (183×228) No trecho “Protejam o Padre Júlio Lancellotti”, a forma verbal destaca contém:","opcoes":["radical + vogal temática + desinência modo-temporal.","radical + vogal temática + sufixo.","raiz + sufixo.","raiz + sufixo modo-temporal e número-pessoa."],"correta":3,"explicacao":"Gabarito: <strong>raiz + sufixo modo-temporal e número-pessoa.</strong>.","banca":"JVL Concursos","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2016,"enunciado":"Na formação e estruturação de palavras da Língua Portuguesa, essas podem apresentar radicais e afixos, como se observa no seguinte grupo:","opcoes":["preservação – vida.","eventos – gases.","global – aquecimento.","água – clima."],"correta":2,"explicacao":"Gabarito: <strong>global – aquecimento.</strong>.","banca":"JVL Concursos","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2017,"enunciado":"Identifique a alternativa em que os prefixos indicam “ação contrária” e “negação”, respectivamente:","opcoes":["distanciamento / isolamento.","posteriormente / pormenorizados.","desmontar / indispensável.","reescritos / complementados.","recorreram / indizível."],"correta":2,"explicacao":"Gabarito: <strong>desmontar / indispensável.</strong>.","banca":"CETAP","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2020,"enunciado":"&#x20;   Acrescentemos que, em português, a alternância vocálica pode ser o que podemos chamar submorfêmica. Isto acontece quando não é ela (como, ao contrário, sucede em fiz, em face de faz + er) a marca única da noção gramatical por expressar. Ela entra no vocábulo formal como um reforço, por assim dizer, de um morfema gramatical. Joaquim Mattoso Câmara Jr. Estrutura da língua portuguesa. 44\\. ed. Petrópolis, RJ: Vozes, 2011 (com adaptações). O tipo de alternância vocálica referido no texto precedente é evidenciado no par","opcoes":["pôde / pode.","povo / povos.","estorvo / estorvos.","bolso / bolsos.","barroco / barrocos."],"correta":1,"explicacao":"Gabarito: <strong>povo / povos.</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2021,"enunciado":"Considerando os aspectos morfológicos dos vocábulos que compõem o texto 8A2-I, assinale a opção correta.","opcoes":["O vocábulo “encontro” (terceiro período) é formado por um morfema lexical, encontr-, acrescido de uma vogal temática, -o.","No vocábulo “pedaço” (primeiro período), a noção de número é expressa por meio de um morfema zero.","No vocábulo “completa” (primeiro período), o morfema -a classifica-se como vogal temática.","No vocábulo “humanidade” (terceiro período), huma e -nidade classificam-se, respectivamente, como morfema lexical e sufixo.","O vocábulo “amigos” (segundo período) é formado pelo processo de derivação sufixal, sendo -s o sufixo que expressa noção de plural."],"correta":1,"explicacao":"Gabarito: <strong>No vocábulo “pedaço” (primeiro período), a noção de número é expressa por meio de um morfema zero.</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2022,"enunciado":"Qual dos vocábulos abaixo, extraídos do texto, apresenta um prefixo?","opcoes":["gigantesca.","&#x20;jornalística.","burro.","incoerente.","mentalmente."],"correta":3,"explicacao":"Gabarito: <strong>incoerente.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2023,"enunciado":"Prefixos são morfemas que se juntam a um radical de modo a derivar novas palavras. Na palavra “hipomineralização”, o prefixo “hipo”, em relação à palavra “mineralização”, acrescenta o sentido de:","opcoes":["Insuficiência ou diminuição.","Qualidade ou abaixo.","Posição superior ou escassez.","&#x20;Carência ou Excesso."],"correta":0,"explicacao":"Gabarito: <strong>Insuficiência ou diminuição.</strong>.","banca":"Prefeitura de Bauru - SP","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2025,"enunciado":"Assinale a alternativa em que todos os vocábulos são formados por derivação prefixal (prefixo).","opcoes":["Incompletas – reconheceu – independência – interagir.","Incompletas – relevante – independência – interagir.","Reconheceu – relevante – independência – inteligência.","Reconheceu – incompletas – independência – inteligência."],"correta":0,"explicacao":"Gabarito: <strong>Incompletas – reconheceu – independência – interagir.</strong>.","banca":"Unoesc","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2030,"enunciado":"As opções a seguir mostram três vocábulos da mesma família, exceto uma, em que há um termo intruso. Assinale-a.","opcoes":["Lua / lunar / lunático.","Paz / pacífico / paciente","Astro / asteroide / astral.","Terra / terreno / desterrar.","Hipódromo / hípica / hipismo."],"correta":1,"explicacao":"Gabarito: <strong>Paz / pacífico / paciente</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2031,"enunciado":"\"\\[...] e entrando no mundo indefesa necessitada de e proteção.\" O prefixo formador da palavra  indefesa tem o mesmo sentido que esse afixo destacado em","opcoes":["O coringa é o arqui-inimigo do Batman.","Foi preciso reeditar todo o filme.","A denúncia foi feita de forma anônima.","O médico proibiu-o de ingerir alimentos sólidos."],"correta":2,"explicacao":"Gabarito: <strong>A denúncia foi feita de forma anônima.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2032,"enunciado":"\"\\[...] embora soubesse da sua existência \\[...]\" segmentação mórfica do verbo destacado se A encontra corretamente estruturada e classificada na alternativa","opcoes":["soube + ss + e (radical + desinência modo-temporal vogal temática).","soub + e + sse (radical + vogal temática + desinência modo-temporal).","soub + e + sse (radical + vogal temática + desinência número-pessoal).","soube + sse (tema + desinência número-pessoal)."],"correta":1,"explicacao":"Gabarito: <strong>soub + e + sse (radical + vogal temática + desinência modo-temporal).</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2033,"enunciado":"Dentre as palavras apresentadas a seguir, assinale aquela cuja estrutura tenha valor semântico diverso ao de “oni”, em “onívora” (linha 27).","opcoes":["iônico.","ônibus.","onicida.","onipresente.","onisciente."],"correta":0,"explicacao":"Gabarito: <strong>iônico.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2034,"enunciado":"A palavra \"respiração\", no último quadrinho, é formada:","opcoes":["Por um radical que serve de base + um prefixo agentivo.","Por um radical que serve de base + um sufixo com valor de ação ou processo.","Por um radical que serve de base + um radical que, composto a ele, denota um valor iterativo.","Por um radical que serve de base + um morfema de plural adicionado à estrutura interna do vocábulo e não ao final, como tradicionalmente ocorre."],"correta":1,"explicacao":"Gabarito: <strong>Por um radical que serve de base + um sufixo com valor de ação ou processo.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2035,"enunciado":"O prefixo latino “in”, que está presente na palavra “inevitavelmente” (ℓ. 21), possui significado de negação e tem o mesmo significado que o prefixo “in” em","opcoes":["infalível.","incriminar.","incluir.","inundar.","influir."],"correta":0,"explicacao":"Gabarito: <strong>infalível.</strong>.","banca":"UFSM","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2036,"enunciado":"Na palavra “afônico” ocorre o prefixo a-, de sentido privativo. A palavra em que esse mesmo prefixo ocorre, com sentido de privação ou negação, é:","opcoes":["aparecer.","adepto.","avermelhado.","amansar.","amoral."],"correta":4,"explicacao":"Gabarito: <strong>amoral.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2038,"enunciado":"Assinale a opção que indica a palavra que exemplifica o a protético, sem valor semântico.","opcoes":["Aparar.","Abraçar.","Atenuar.","Amostrar.","Aguardar."],"correta":3,"explicacao":"Gabarito: <strong>Amostrar.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2039,"enunciado":"Assinale a opção que apresenta o par de palavras em que o a final é identificado como desinência de gênero.","opcoes":["fala / página.","caixa / boca.","larga / professora.","bela / letra.","multa / égua."],"correta":2,"explicacao":"Gabarito: <strong>larga / professora.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2040,"enunciado":"A palavra “amassado” é formada pelo processo de:","opcoes":["Derivação prefixal.","Derivação parassintética.","Derivação regressiva.","Derivação sufixal."],"correta":3,"explicacao":"Gabarito: <strong>Derivação sufixal.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2041,"enunciado":"O prefixo “in-” em “inflexível” traz um sentido negativo à palavra “flexível”, significando algo que não é flexível. Sendo assim, são palavras na qual o prefixo “in-” tem sentido negativo, EXCETO:","opcoes":["Inalcançável.","Indicativo.","Inexistente.","Indisponível.","Invisível."],"correta":1,"explicacao":"Gabarito: <strong>Indicativo.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2043,"enunciado":"Considerando o processo de formação de palavras da língua portuguesa,","opcoes":["na palavra boyzinha, o sufixo -zinha é utilizado, tão somente, para indicar a relação de afetividade do eu-lírico com o seu objeto de desejo.","na palavra boyzinha, o sufixo -zinha indica a pequenez do objeto de desejo do eu-lírico e expressa, de forma irônica, o fato de ele ter sido abandonado.","na palavra galinha, o sufixo -inha indica, de maneira irônica, o modo promíscuo com que o eu lírico conduz a sua vida afetiva.","na palavra galinha, o sufixo -inha indica, de modo conotativo e pejorativo, o diminutivo feminino da ave da família dos galináceos."],"correta":0,"explicacao":"Gabarito: <strong>na palavra boyzinha, o sufixo -zinha é utilizado, tão somente, para indicar a relação de afetividade do eu-lírico com o seu objeto de desejo.</strong>.","banca":"FUNCERN","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2044,"enunciado":"Assinale a opção que indica as duas palavras que pertencem a famílias diferentes.","opcoes":["mão / manual.","cabeça / cabeçada.","braço / braçada.","cabelo / cabeleira.","olho / piolho."],"correta":4,"explicacao":"Gabarito: <strong>olho / piolho.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2045,"enunciado":"Na maior parte dos casos, o prefixo “des-”, quando adicionado a um verbo, indica ação contrária àquela originalmente expressa pela forma verbal. Nesse sentido, qual das palavras abaixo NÃO é formada com esse prefixo e significado em Língua Portuguesa?","opcoes":["Desertificar.","Desafivelar.","Desgrudar.","Desaparecer.","Desembarcar."],"correta":0,"explicacao":"Gabarito: <strong>Desertificar.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2046,"enunciado":"Considerando a palavra “protelados” (l. 13), analise as assertivas a seguir, assinalando V, se verdadeiras, ou F, se falsas. ( ) Trata-se de um substantivo simples e comum. ( ) Um sinônimo possível para a palavra é “adiados”. ( ) “Protelados” é da mesma família de palavras do verbo “protelar”. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["V – V – V.","V – F – F.","V – V – F.","F – V – V.","&#x20;F – F – V."],"correta":3,"explicacao":"Gabarito: <strong>F – V – V.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2047,"enunciado":"Assinale a alternativa em que o significado do prefixo destacado foi INCORRETAMENTE indicado.","opcoes":["“impessoal” (12º§) im- = ausência.","“desconexão” (5º§) des- = separação.","“transparente” (9º§) trans- = através de.","“submeteu” (8º§) sub- = posição superior."],"correta":3,"explicacao":"Gabarito: <strong>“submeteu” (8º§) sub- = posição superior.</strong>.","banca":"Instituto Consulplan","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2048,"enunciado":"Na palavra “consentimento”, o elemento mórfico em destaque significa “ato de realizar uma ação expressa pelo verbo de base”. Assim, “consentimento” significa “ato de consentir”. Esse mesmo elemento em destaque está presente, com o mesmo sentido, na palavra:","opcoes":["cimento","fragmento","monumento","pensamento"],"correta":3,"explicacao":"Gabarito: <strong>pensamento</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2050,"enunciado":"Assinale a alternativa em que todas as palavras são formadas pelo processo de derivação prefixal:","opcoes":["Inesgotável, etarismo.","Pioneira, autoral.","Escrevivência, reconhecidamente.","Brasileiras, escritoras.","Demérito, desajuste."],"correta":4,"explicacao":"Gabarito: <strong>Demérito, desajuste.</strong>.","banca":"FAU","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2051,"enunciado":"Em qual dos vocábulos abaixo a partícula “auto-” NÃO possui o mesmo sentido que ocorre na palavra “autorrelato”?","opcoes":["autodidata","autoestrada","autonomia","autoestima"],"correta":1,"explicacao":"Gabarito: <strong>autoestrada</strong>.","banca":"DECORP","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2056,"enunciado":"Dentre os conjuntos de palavras a seguir, aquele em que todas as palavras dadas apresentam sufixos é:","opcoes":["guarda-costas; capim-limão; erva-doce.","aguardente; fidalgo; planalto.","desprezo; infeliz; anarquia.","enrolação; tratamento; fielmente.","calma; tristeza; árvores."],"correta":3,"explicacao":"Gabarito: <strong>enrolação; tratamento; fielmente.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2058,"enunciado":"No texto, encontramos vocábulos como “normalizar”, “anormal” e “normalização”. Em relação à estrutura mórfica, assinale a alternativa correta.","opcoes":["Foram formados pelo processo de composição.","Possuem, em comum, a presença de um mesmo radical.","Seus sufixos inserem-nos na mesma classe gramatical.","Trazem um morfema que aponta a marcação de gênero.","Têm um prefixo que confere a todos o mesmo sentido."],"correta":1,"explicacao":"Gabarito: <strong>Possuem, em comum, a presença de um mesmo radical.</strong>.","banca":"IBFC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2060,"enunciado":"Assinale o processo de formação de palavras ocorrido nas palavras “cara-metade”, “conscienciosidade” e “indispensável”.","opcoes":["Composição por aglutinação, derivação sufixal e derivação prefixal.","Composição por justaposição, derivação sufixal e derivação parassintética.","Derivação prefixal, composição por aglutinação e derivação sufixal.","Derivação sufixal, composição por justaposição e derivação parassintética.","Composição por justaposição, derivação sufixal e derivação imprópria."],"correta":1,"explicacao":"Gabarito: <strong>Composição por justaposição, derivação sufixal e derivação parassintética.</strong>.","banca":"CETREDE","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2061,"enunciado":"O vocábulo empregado no texto que não apresenta desinência de gênero é:","opcoes":["Brasileiros.","Básico.","Estudante.","Públicas."],"correta":2,"explicacao":"Gabarito: <strong>Estudante.</strong>.","banca":"ADM\\&TEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2062,"enunciado":"Na palavra \"desleal\", o prefixo \"des-\" indica:","opcoes":["Afirmação ou intensidade.","Lugar ou direção.","Negação ou oposição.","Tempo ou anterioridade."],"correta":2,"explicacao":"Gabarito: <strong>Negação ou oposição.</strong>.","banca":"EVO Concursos","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2063,"enunciado":"“Depois que isso é feito, essa técnica o desenrola em uma imagem plana” (4º parágrafo). O elemento mórfico em destaque é classificado como:","opcoes":["prefixo","radical","sufixo","tema"],"correta":0,"explicacao":"Gabarito: <strong>prefixo</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2064,"enunciado":"A palavra “publicamente”, utilizada no texto, é formada por meio de:","opcoes":["Derivação sufixal.","Derivação regressiva.","Derivação prefixal.","Composição por aglutinação."],"correta":0,"explicacao":"Gabarito: <strong>Derivação sufixal.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2066,"enunciado":"Analise as palavras “inesquecível”, “ultrarrespeitador” e “encerador” quanto aos seus elementos mórficos de formação. Pode-se dizer que as três palavras têm em comum:","opcoes":["Um de seus processos de formação, que inclui a incorporação de prefixos.","Um mesmo radical a partir do qual se formaram novas palavras derivadas.","Prefixos de um mesmo campo semântico.","Sufixos que formam palavras derivadas de apenas uma classe gramatical.","O mesmo morfema flexional de gênero."],"correta":0,"explicacao":"Gabarito: <strong>Um de seus processos de formação, que inclui a incorporação de prefixos.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2068,"enunciado":"Assinale a alternativa em que todas as palavras apresentam prefixo de negação:","opcoes":["Imoralidade, despeito, descendência;","Infecção, indústria, desigualdade;","Impaciência, descrença, inconveniência;","Invasão, inferioridade, desconfiança."],"correta":2,"explicacao":"Gabarito: <strong>Impaciência, descrença, inconveniência;</strong>.","banca":"EVO Concursos","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2069,"enunciado":"Em relação à estrutura e formação de palavras, analise as afirmativas a seguir: I.Os sufixos 'aria' e 'eria' são acrescentados aos vocábulos podendo indicar lugar, como nos exemplos: tesouraria e sorveteria. II.O sufixo \"anzil\" é utilizado para formar diminutivos, como no exemplo \"corpanzil\". III.O prefixo do vocábulo 'eufonia' tem significado de 'bom'. IV.Os vocábulos 'enriquecer', 'histórico' e 'pessoa' são formados por , respectivamente, derivação parassintética, derivação por sufixação e derivação por sufixação. V.Os vocábulos 'infeliz' e 'contrassenso' são formadas por derivação prefixal. Estão corretas:","opcoes":["Apenas II, e V.","Apenas I, II, III e V.","Apenas I, III e V.","Apenas II, IV e V."],"correta":2,"explicacao":"Gabarito: <strong>Apenas I, III e V.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2070,"enunciado":"Sobre a formação de palavras, assinale a alternativa que apresenta uma palavra formada por prefixação.","opcoes":["Beleza.","Entardecer.","Antebraço.","Vinagre."],"correta":2,"explicacao":"Gabarito: <strong>Antebraço.</strong>.","banca":"Instituto Fênix","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2071,"enunciado":"Quanto à estrutura das palavras, assinale (C) correto ou (I) incorreto e marque a alternativa devida. ( ) Radical é o morfema originário e irredutível que contém o núcleo significativo comum a uma família linguística. ( ) Raiz é o morfema que funciona como o segmento lexical da palavra, opondo-se ao segmento que lhe assinala (por meio de outros morfemas) as flexões e a derivação. ( ) Desinência é o morfema indicativo das flexões das palavras, isto é, das variações por que elas passam para expressar as categorias gramaticais de gênero e número (nos nomes) e de pessoa, número, modo e tempo (nos verbos). ( ) Vogal temática é o morfema que caracteriza nomes e verbos portugueses, reunindo-os em classes morfológicas estanques. ( ) Tema é o radical ampliado por uma vogal temática. Assim, do radical ros- obter-se-á, pela adjunção da vogal temática nominal a, o tema rosa-; identicamente, o radical trabalh-, acrescido da vogal temática da 1ª conjugação, dar-nos-á o tema trabalha-. ( ) Afixos são morfemas destinados à formação de derivados.","opcoes":["C – C – C – C – C – I.","C – C – I – C – I – C.","I – I – C – C – C – C.","C – C – I – I – C – C.","C – C – C – C – C – C."],"correta":2,"explicacao":"Gabarito: <strong>I – I – C – C – C – C.</strong>.","banca":"MSConcursos","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2072,"enunciado":"Sobre a formação das palavras presentes na oração \"Precisaremos reeditar o debate sobre o papel dos estudantes na reforma do ensino médio ao entardecer\", é correto afirmar apenas que a palavra","opcoes":["\"precisaremos\" é formada por derivação sufixal.","\"debate\" é formada por derivação prefixal.","\"entardecer\" é formada por derivação prefixal e sufixal.","\"reeditar\" é formada por derivação prefixal."],"correta":3,"explicacao":"Gabarito: <strong>\"reeditar\" é formada por derivação prefixal.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2073,"enunciado":"Nas palavras apresentadas a seguir, foram destacados diferentes elementos mórficos. Identifique aquela cuja parte em destaque corresponde a um morfema de número.","opcoes":["moça.","livreiro.","cachoeiras.","inanimado.","escrevente."],"correta":2,"explicacao":"Gabarito: <strong>cachoeiras.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2074,"enunciado":"O prefixo latino “in-” pode expressar negação. Sendo assim, em qual dos vocábulos do texto a ocorrência de “in-” expressa essa ideia?","opcoes":["Internet.","Involuntários.","Inteligência.","Imprensa.","Interessante."],"correta":1,"explicacao":"Gabarito: <strong>Involuntários.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2075,"enunciado":"Assinale a alternativa que apresenta uma afirmação INCORRETA sobre a palavra “subterrâneo”.","opcoes":["Apresenta um prefixo.","Possui somente um radical.","Apresenta um sufixo.","Possui dois radicais.","É uma palavra derivada."],"correta":3,"explicacao":"Gabarito: <strong>Possui dois radicais.</strong>.","banca":"Fundação CETREDE","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2077,"enunciado":"Assinale a alternativa que indica a correta segmentação morfológica da palavra inexplicável (linha 05).","opcoes":["in-explic-á-vel.","in-e-xplic-ável.","in-expli-cáv-el.","i-nex-pli-cá-vel."],"correta":0,"explicacao":"Gabarito: <strong>in-explic-á-vel.</strong>.","banca":"FCPC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2078,"enunciado":"Analise as palavras a seguir quanto aos seus elementos mórficos. O conjunto em que todas as palavras dadas apresentam prefixos que equivalem em significado é:","opcoes":["anacrônico; anônimo; anelídeo.","submissão; hipogeu; hemisfério.","extraordinário; intracontinental; antebraço.","infeliz; desleal; ingerir.","dígrafo; bípede; biênio."],"correta":4,"explicacao":"Gabarito: <strong>dígrafo; bípede; biênio.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["formacaoPalavras","digrafos"]},{"id":2079,"enunciado":"\"No entanto, ter que processar e se adaptar a coisas novas pode ser exaustivo, mesmo para uma criança pequena com energia inesgotável.\" O prefixo 'in' da palavra 'inesgotável' representa sentido contrário. Em uma das alternativas a seguir o prefixo NÃO está de acordo com o seu significado. Identifique-o.","opcoes":["Anfíbio (= em volta de).","Dispepsia (= dificuldade).","Hipocrisia (= posição inferior).","Pluricelular (= muito)."],"correta":0,"explicacao":"Gabarito: <strong>Anfíbio (= em volta de).</strong>.","banca":"Unesc","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":2081,"enunciado":"Na palavra SURGIMENTO, o elemento destacado é um sufixo. A única palavra que apresenta esse mesmo sufixo, com significado e função semelhantes, é:","opcoes":["fragmento","casamento","instrumento","cumprimento"],"correta":1,"explicacao":"Gabarito: <strong>casamento</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2082,"enunciado":"A palavra \"irremediável\" em \"Se eu pudesse me resumir, diria que sou irremediável!\" possui a seguinte estrutura morfológica: Prefixo: \"ir-\", Radical: \"remedi-\", e o Sufixo: \"-ável\" O sufixo é um elemento que forma adjetivos e indica a capacidade ou possibilidade de algo ser feito. A junção desses elementos forma um adjetivo que descreve algo que não pode ser remediado.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2086,"enunciado":"O vocábulo do texto que não apresenta desinência de gênero é:","opcoes":["Cientista.","Extremo.","Própria.","Energética."],"correta":0,"explicacao":"Gabarito: <strong>Cientista.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2088,"enunciado":"Na palavra \"desemprego\", o prefixo \"des-\" indica:","opcoes":["Intensificação da ação expressa pela palavra \"emprego\".","Condição de estabilidade no emprego.","Repetição do ato de empregar.","Negação ou ausência do estado de emprego."],"correta":3,"explicacao":"Gabarito: <strong>Negação ou ausência do estado de emprego.</strong>.","banca":"Instituto Fênix","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2089,"enunciado":"O prefixo da palavra insalubre possui valor semântico de:","opcoes":["Oposição.","Interior.","Posição inferior.","Negação."],"correta":3,"explicacao":"Gabarito: <strong>Negação.</strong>.","banca":"Gama Consult","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2090,"enunciado":"Assinale a alternativa em que a palavra estrangeira é popularmente utilizada em língua portuguesa por meio do processo de formação por derivação sufixal.","opcoes":["Time’s Up.","biojoias.","tailleurs.","looks.","marketeiros."],"correta":4,"explicacao":"Gabarito: <strong>marketeiros.</strong>.","banca":"FAUEL","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2091,"enunciado":"Na palavra “INFELIZMENTE”, há:","opcoes":["apenas um sufixo","apenas um prefixo","apenas dois prefixos","um prefixo e um sufixo"],"correta":3,"explicacao":"Gabarito: <strong>um prefixo e um sufixo</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2092,"enunciado":"Qual das palavras a seguir é um exemplo de neologismo:","opcoes":["Bebível.","Tique-taque.","Bombom.","Invenção.","Computação."],"correta":0,"explicacao":"Gabarito: <strong>Bebível.</strong>.","banca":"FACET Concursos","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2093,"enunciado":"Possui o mesmo radical a seguinte sequência de palavras:","opcoes":["Plantio, planalto, planície.","Girassol, girafa, gigante.","Padeiro, minipão, paçoca.","Falar, fazer, falir.","Sol, ensolarado, solar."],"correta":4,"explicacao":"Gabarito: <strong>Sol, ensolarado, solar.</strong>.","banca":"FACET Concursos","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2094,"enunciado":"Dadas as assertivas: I. Podem ocorrer transformações na configuração de um idioma, ao longo do tempo, e uma delas pode incidir na renovação de seu repertório vocabular; II. No que diz respeito à organização lexical de uma língua, os trocadilhos têm a mesma estrutura e composição dos neologismos; e III. Os neologismos especificados no texto, ainda que sejam estranhos, apresentam plausibilidade na sua composição e significação. Está(Estão) correta(s) a(s) seguinte(s) assertiva(s), de acordo com o texto:","opcoes":["I e II","I e III","II e III","I, apenas","III, apenas"],"correta":1,"explicacao":"Gabarito: <strong>I e III</strong>.","banca":"FACET Concursos","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2096,"enunciado":"A fim de promover aprofundamento do conhecimento sistêmico que envolve os vários níveis da organização linguística, tais como os dos âmbitos léxico-semântico e morfológico, o professor selecionou um grupo de vocábulos extraídos de texto previamente estudado com o objetivo didático de guiar as observações e percepções dos estudantes: fast-girl – love – they-that – some – more – and – cat – run – the – book – time – sad Em relação aos vocábulos referidos, o critério que justifica as escolhas feitas pelo professor é:","opcoes":["Não é possível modificar um verbo usando um morfema.","Um morfema livre pode ser lexical ou gramatical/funcional.","Os morfemas presos podem ser derivacionais ou inflexionais.","Os termos “sílaba” e “morfema” descrevem o mesmo fenômeno."],"correta":1,"explicacao":"Gabarito: <strong>Um morfema livre pode ser lexical ou gramatical/funcional.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2097,"enunciado":"O sufixo -ada é empregado muitas vezes para indicar “golpe ou agressão”, como no seguinte caso:","opcoes":["cadeirada, bofetada.","lixarada, estudantada.","temporada, estada.","aguada, baixada.","torrada, feijoada."],"correta":0,"explicacao":"Gabarito: <strong>cadeirada, bofetada.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2099,"enunciado":"Julgue o item que se segue.\nOs sufixos na língua portuguesa representam uma estrutura morfológica versátil e produtiva, sendo elementos adicionados ao final das palavras que desempenham um papel crucial na formação de novos termos, na derivação de palavras e na flexão gramatical, refletindo a dinâmica evolutiva e adaptativa do sistema linguístico.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2100,"enunciado":"Julgue o item que se segue.\nO significado instrumental das palavras está intrinsecamente ligado aos morfemas, tais como prefixos, sufixos e desinências, que desempenham um papel crucial nas combinações gramaticais, conferindolhes um aspecto estrutural e instrumental na expressão linguística.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2106,"enunciado":"Observe os pares de palavras a seguir: omitir → omissão faltar → falta citar → citação ocorrer → ocorrência Ocorre derivação sufixal","opcoes":["em um par, apenas.","em dois pares, apenas.","em três pares, apenas.","nos quatro pares."],"correta":2,"explicacao":"Gabarito: <strong>em três pares, apenas.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2021,"temas_relacionados":["formacaoPalavras"]},{"id":2107,"enunciado":"Analise as afirmativas, tendo em vista o texto 06. I. O prefixo “-ultra” insere, na palavra “ultraprocessados”, a ideia de excesso. II. O termo ‘“palavrão”’ assume, no texto, o significado de palavra grosseira. III. O texto informa que balas e biscoitos são alimentos muito processados. IV. O sufixo “-ão”, presente no termo ‘“palavrão”’, indica valor aumentativo. V. As palavras “ultraprocessados” e ‘“palavrão”’ contêm sufixo e prefixo. Estão CORRETAS as afirmativas","opcoes":["I, IV e V, apenas.","I, III e IV, apenas.","I, II e IV, apenas.","&#x20;II, III e V, apenas.","&#x20;III, IV e V, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, III e IV, apenas.</strong>.","banca":"COTEC","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2108,"enunciado":"Na palavra PRIVATIZAÇÃO, o elemento destacado é:","opcoes":["um radical que indica “venda” ou “doação”","um sufixo que indica ato ou ação de fazer algo","o mesmo prefixo encontrado na palavra AÇÃO","o mesmo sufixo encontrado na palavra NAÇÃO","um prefixo sempre empregado na formação de verbos"],"correta":1,"explicacao":"Gabarito: <strong>um sufixo que indica ato ou ação de fazer algo</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2109,"enunciado":"Marque a alternativa incorreta quanto à classificação dos elementos mórficos destacados nas seguintes palavras do texto:","opcoes":["global – AL - sufixo.","pressionamos – MOS – desinência número-pessoal.","humana – A – desinência de gênero.","estamos - ESTA – radical.","impedir – I – vogal temática verbal."],"correta":3,"explicacao":"Gabarito: <strong>estamos - ESTA – radical.</strong>.","banca":"IBADE","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2111,"enunciado":"\\[...] A chuva, em gotas glaciais, Chora monotonamente. \\[...] E enquanto anoitece, vou Lendo, sossegado e só, As cartas que meu avô Escrevia a minha avó. \\[...] Cartas de antes do noivado… Cartas de amor que começa, Inquieto, maravilhado, E sem saber o que peça. \\[...] (BANDEIRA. M. Cartas de meu avô. In: Estrela da Vida Inteira. 20 ed. Rio de Janeiro: Nova Fronteira, 1993. p. 52 e 53.) Assinale a alternativa que indique, respectivamente, os processos de formação dos vocábulos “monotonamente”, “anoitece” e “começa”.","opcoes":["Composição por aglutinação, derivação por sufixação e redução.","&#x20;Derivação parassintética, composição por aglutinação e redução.","Derivação por prefixação, derivação parassintética e derivação regressiva.","Derivação por sufixação, derivação parassintética e derivação regressiva."],"correta":3,"explicacao":"Gabarito: <strong>Derivação por sufixação, derivação parassintética e derivação regressiva.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2113,"enunciado":"É correto afirmar que a palavra em que há apenas derivação prefixal em sua formação é","opcoes":["“desigualdades”.","“incorreta”.","“inegável”.","“desinformativo”."],"correta":1,"explicacao":"Gabarito: <strong>“incorreta”.</strong>.","banca":"UECE-CEV","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2114,"enunciado":"Observe os vocábulos dispostos no quadro a seguir. Imagem associada para resolução da questão Qual(is) desses vocábulos relacionados apresenta(m) o prefixo e o sufixo simultaneamente acoplados ao radical, formando palavra(s) derivada(s) por parassíntese?","opcoes":["As palavras “praieiro” e “crueldade”.","As palavras “inutilizar”, semeadura” e “lucidez”.","Somente a palavra “embarcação”.","As palavras “inutilizar” e “crueldade”.","Somente a palavra “inutilizar”."],"correta":2,"explicacao":"Gabarito: <strong>Somente a palavra “embarcação”.</strong>.","banca":"CETREDE","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2116,"enunciado":"As palavras “lugarejo” e “palhoça”, encontradas no primeiro parágrafo do texto, apresentam que processo em sua formação respectivamente?","opcoes":["Derivação sufixal e derivação sufixal","Derivação prefixal e derivação sufixal","Derivação prefixal e derivação prefixal","Derivação parassintética e derivação prefixal e sufixal"],"correta":0,"explicacao":"Gabarito: <strong>Derivação sufixal e derivação sufixal</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2118,"enunciado":"Observe a palavra 'infraestrutura'. Esse termo é formado por meio de qual processo de formação de palavras?","opcoes":["Derivação prefixal","Derivação sufixal","Aglutinação","Justaposição","Composição por sufixação"],"correta":0,"explicacao":"Gabarito: <strong>Derivação prefixal</strong>.","banca":"IDHTEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2120,"enunciado":"Analise o termo e assinale a alternativa correta: “antipatia”","opcoes":["Na palavra acima, não há a presença de prefixo, nem de sufixo.","Na palavra acima, há a presença de um prefixo e de um sufixo.","Na palavra acima, há a presença de um sufixo.","&#x20;Na palavra acima, há a presença de um prefixo."],"correta":3,"explicacao":"Gabarito: <strong>&#x20;Na palavra acima, há a presença de um prefixo.</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2121,"enunciado":"Quanto à formação das palavras, marque a alternativa, onde temos uma derivação por prefixação.","opcoes":["Supersônico.","Felizmente.","Desalmado.","Enegrece.","Dentista."],"correta":0,"explicacao":"Gabarito: <strong>Supersônico.</strong>.","banca":"MSConcursos","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2122,"enunciado":"O vocábulo do texto cujo prefixo tem valor semântico distinto dos demais é:","opcoes":["inaceitável;","impossível;","impensável;","incuráveis;","informações."],"correta":4,"explicacao":"Gabarito: <strong>informações.</strong>.","banca":"NCE-UFRJ","ano":2006,"temas_relacionados":["formacaoPalavras"]},{"id":2126,"enunciado":"Assinale a alternativa em que todos os vocábulos são formados pelo mesmo prefixo, com o mesmo sentido e origem.","opcoes":["abuso - abster - abdicar","bisavô - bilhete - biscoito","incorrer - incapaz - induzir","antipatia - antigo - antídoto","advogado - adjunto - adulação"],"correta":0,"explicacao":"Gabarito: <strong>abuso - abster - abdicar</strong>.","banca":"FEPESE","ano":2008,"temas_relacionados":["formacaoPalavras"]},{"id":2127,"enunciado":"Ao comparar o uso do sufixo “-inho”, no texto Il, com o presente na palavra “tristinho” do texto IV; é possível afirmar que nesse vocábulo o morfema indica:","opcoes":["ironia.","intensificação.","linguagem infantil.","a suavização de uma ideia.","tamanho reduzido."],"correta":1,"explicacao":"Gabarito: <strong>intensificação.</strong>.","banca":"ESPP","ano":2013,"temas_relacionados":["formacaoPalavras"]},{"id":2128,"enunciado":"O sufixo “-inho”, em Língua Portuguesa, é responsável pela indicação de diminutivo. Contudo, dependendo do contexto, tal morfema pode construir ainda outros sentidos. Nos vocábulos “espertinho” e “jeitinho”, o sufixo “-inho” apresenta o mesmo sentido que encontramos em:","opcoes":["Aquele filminho em nada me surpreendeu.","Amorzinho, obrigada pelas flores!","Preciso comprar fraldinhas novas.","Vivia se olhando no espelhinho da carteira.","Só um minutinho de atenção, por favor!"],"correta":0,"explicacao":"Gabarito: <strong>Aquele filminho em nada me surpreendeu.</strong>.","banca":"ESPP","ano":2013,"temas_relacionados":["formacaoPalavras"]},{"id":2130,"enunciado":"Assim como em “desimpedido” (𝓁. 30), o prefixo indica oposição, negação ou falta em:","opcoes":["desgastada.","embuste.","investimento.","independente."],"correta":3,"explicacao":"Gabarito: <strong>independente.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["formacaoPalavras"]},{"id":2132,"enunciado":"Das palavras abaixo, aquela cujo sufixo apresenta valor semântico de “agente” é:","opcoes":["“cuidadores”","“doméstico”","“ocupacional”","“ambulatórios”"],"correta":0,"explicacao":"Gabarito: <strong>“cuidadores”</strong>.","banca":"CEPUERJ","ano":2013,"temas_relacionados":["formacaoPalavras"]},{"id":2134,"enunciado":"O par de vocábulos derivados cujos sufixos acrescentam às formas primitivas noções inteiramente diversas é:","opcoes":["espanhola / interiorano;","probabilidade / gentileza;","mutação / julgamento;","midiático / familiar;","reservatório / folhagem."],"correta":4,"explicacao":"Gabarito: <strong>reservatório / folhagem.</strong>.","banca":"FJPF","ano":2006,"temas_relacionados":["formacaoPalavras"]},{"id":2136,"enunciado":"Na palavra \"supermercados\", o prefixo \"super\" tem distinto valor do mesmo prefixo no vocábulo:","opcoes":["supercílio;","superabundância;","supercondutor;","superdotado;","superprodução."],"correta":0,"explicacao":"Gabarito: <strong>supercílio;</strong>.","banca":"NCE-UFRJ","ano":2007,"temas_relacionados":["formacaoPalavras"]},{"id":2137,"enunciado":"A palavra “invencidos”, que aparece no 5º§ do texto, foi formada pelo processo de","opcoes":["derivação prefixal.","composição prefixal.","derivação prefixal e sufixal.","composição sufixal e prefixal."],"correta":2,"explicacao":"Gabarito: <strong>derivação prefixal e sufixal.</strong>.","banca":"CONSULPLAN","ano":2014,"temas_relacionados":["formacaoPalavras"]},{"id":2138,"enunciado":"A palavra “reajuste”, linha 37, sofreu os seguintes processos de formação:","opcoes":["ajuste → reajustar → ajustar → reajuste.","justo → ajustar → reajustar → reajuste.","ajuste → ajustar → reajustar → reajuste.","justo → reajustar → ajustar → reajuste."],"correta":1,"explicacao":"Gabarito: <strong>justo → ajustar → reajustar → reajuste.</strong>.","banca":"UECE-CEV","ano":2008,"temas_relacionados":["formacaoPalavras"]},{"id":2139,"enunciado":"O processo de formação da palavra \"anfiteatro\" (v.1 e 17) é denominado","opcoes":["composição por justaposição.","derivação imprópria.","derivação prefixal.","derivação parassintética."],"correta":2,"explicacao":"Gabarito: <strong>derivação prefixal.</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"temas_relacionados":["formacaoPalavras"]},{"id":2141,"enunciado":"A palavra “imaturas” é formada por","opcoes":["justaposição","aglutinação","derivação","abreviação"],"correta":2,"explicacao":"Gabarito: <strong>derivação</strong>.","banca":"IBFC","ano":2013,"temas_relacionados":["formacaoPalavras"]},{"id":2142,"enunciado":"Do ponto de vista morfológico, a palavra “libertária” é formada por","opcoes":["composição, visto que apresenta dois radicais seguidos de um sufixo.","justaposição, porque a palavra não perde som no processo de formação.","aglutinação, visto que, se juntar dois radicais diferentes, a palavra perde alguns sons.","derivação, porque forma-se com o acréscimo de um sufixo, que altera parcialmente o significado do radical."],"correta":3,"explicacao":"Gabarito: <strong>derivação, porque forma-se com o acréscimo de um sufixo, que altera parcialmente o significado do radical.</strong>.","banca":"CONSULPLAN","ano":2014,"temas_relacionados":["formacaoPalavras"]},{"id":2143,"enunciado":"Assinale a alternativa referente ao processo de formação de palavras de que resultou o vocábulo \"nadegômetros\" (e. 33).","opcoes":["Derivação prefixal.","Derivação imprópria.","Hibridismo.","Reduplicação.","Justaposição."],"correta":2,"explicacao":"Gabarito: <strong>Hibridismo.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["formacaoPalavras"]},{"id":2144,"enunciado":"Tal como \"escritores\" e \"escreviam\" (e. 2), há vocábulos que se agrupam em tomo de um radical comum, que, às vezes, se conserva intacto ou sofre alterações ao longo do tempo. Assinale a alternativa que apresenta palavras pertencentes à mesma família.","opcoes":["Povoar; povaréu; despovoamento; superpopulação.","Povoar; povo; popúleo; popular.","Povoar; poltronice; popularizar; despovoar.","Povoar; populacho; politizado; populista.","Povoar; populário; despovoar; polvorosa."],"correta":0,"explicacao":"Gabarito: <strong>Povoar; povaréu; despovoamento; superpopulação.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["formacaoPalavras"]},{"id":2145,"enunciado":"São palavras formadas pelo mesmo processo morfológico:","opcoes":["imensidade – insatisfeita – curvada.","perfeita – saudade – deleita.","voando – profundo – sonhando.","encher – morrem – acordo.","poetisa – inspiração – claridade."],"correta":4,"explicacao":"Gabarito: <strong>poetisa – inspiração – claridade.</strong>.","banca":"FUNRIO","ano":2009,"temas_relacionados":["formacaoPalavras"]},{"id":2146,"enunciado":"São formadas por processos diferentes as palavras","opcoes":["\"perigosamente\" (linha 1) / \"totalitarismo\" (linha 5).","\"triunfo\" (linha 2) / \"conquista\" (linha 4).","\"poder\" (linha 15) / \"ameaças\" (linha 24).","\"desautoriza\" (linha 16) / \"internacional\" (linha 21).","\"pseudolibertária\" (linha 23) / \"neoconservadorismo\" (linha 26)."],"correta":2,"explicacao":"Gabarito: <strong>\"poder\" (linha 15) / \"ameaças\" (linha 24).</strong>.","banca":"CEFET-BA","ano":2006,"temas_relacionados":["formacaoPalavras"]},{"id":2147,"enunciado":"A palavra riqueza deriva de rico. Pela mesma analogia, temos como incorreta a alternativa:","opcoes":["Gentileza – gentil","Dureza – duro","Realeza – real","Alteza – alto","Burgueza – burguês"],"correta":4,"explicacao":"Gabarito: <strong>Burgueza – burguês</strong>.","banca":"Intelectus","ano":2006,"temas_relacionados":["formacaoPalavras"]},{"id":2148,"enunciado":"A palavra recompensada é formada pelo processo de:","opcoes":["Derivação imprópria","Composição por justaposição","Derivação prefixal e sufixal","Composição por aglutinação","Derivação parassintética"],"correta":2,"explicacao":"Gabarito: <strong>Derivação prefixal e sufixal</strong>.","banca":"Intelectus","ano":2006,"temas_relacionados":["formacaoPalavras"]},{"id":2149,"enunciado":"O verbo disponibilizar (2º parágrafo) é grafado com o sufixo “izar” por não possuir um “s” na terminação de seu radical. Essa regra também atinge a palavra:","opcoes":["Catequizar","Batizar","Integralizar","Hipnotizar","Sintetizar"],"correta":2,"explicacao":"Gabarito: <strong>Integralizar</strong>.","banca":"Intelectus","ano":2006,"temas_relacionados":["formacaoPalavras"]},{"id":2150,"enunciado":"Assinale a alternativa que não apresenta a correta análise do processo de formação de palavra.","opcoes":["A palavra \"Hackeamento\" é um neologismo.","a palavra hackeamento foi formada a partir de um processo de formação de palavras chamado Sufixação.","A palavra desestabilizar foi formada pelo processo de prefixação.","A palavra redobrar foi formada por prefixação.","Generalizada é uma palavra formada por sufixação."],"correta":2,"explicacao":"Gabarito: <strong>A palavra desestabilizar foi formada pelo processo de prefixação.</strong>.","banca":"IF Sertão - PE","ano":2019,"temas_relacionados":["formacaoPalavras"]},{"id":2152,"enunciado":"Relacione as palavras aos respectivos processos de formação. 1\\. Desonesta. 2\\. Enlouquecer. 3\\. Planura. 4\\. Pouso. 5\\. Embora. ( ) Derivação sufixal. ( ) Derivação regressiva. ( ) Composição por aglutinação. ( ) Derivação prefixal. ( ) Derivação parassintética. A sequência está correta em","opcoes":["3, 5, 4, 2, 1","3, 4, 5, 1, 2","4, 3, 2, 1, 5","5, 4, 1, 2, 3","2, 1, 3, 4, 5"],"correta":1,"explicacao":"Gabarito: <strong>3, 4, 5, 1, 2</strong>.","banca":"IDECAN","ano":2013,"temas_relacionados":["formacaoPalavras"]},{"id":2153,"enunciado":"Assinale a alternativa que preenche corretamente as lacunas da frase abaixo: “Da mesma forma que os italianos e japoneses \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ no Brasil no século passado, hoje os brasileiros \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ para a Europa e para o Japão à busca de uma vida melhor; internamente os brasileiros \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ para o Sul, pelo mesmo motivo.”","opcoes":["migraram - imigram - emigram","imigraram - emigram - migram","emigraram - migram - imigram","imigraram - migram - emigram","emigraram - imigram - migram"],"correta":1,"explicacao":"Gabarito: <strong>imigraram - emigram - migram</strong>.","banca":"PROMUN","ano":2016,"temas_relacionados":["formacaoPalavras"]},{"id":2154,"enunciado":"A palavra formada por acréscimo de um prefixo é:","opcoes":["recurso","despesas","seguridade","execução","desonerações"],"correta":4,"explicacao":"Gabarito: <strong>desonerações</strong>.","banca":"CEPERJ","ano":2012,"temas_relacionados":["formacaoPalavras"]},{"id":2155,"enunciado":"Atente para o seguinte trecho e as afirmações a respeito da formação das palavras “aprendem” e “aprender”: “O Amyr Klink disse que as crianças aprendem “construindo” uma casa. Concordo. Para aprender uma coisa é preciso fazê-la”. (linhas 89-91) I. Em “aprendem”, aprend- é prefixo, enquanto -em é sufixo. II. Em “aprender”, aprend- é radical, -e é vogal temática, e -r, desinência número-pessoal. III. Em “aprender”, aprend- é radical, -e é vogal temática, e -r, desinência modo-temporal. IV. Em “aprender” e em “aprendem”, a junção de aprend- e -e forma o tema. V. Em “aprendem”, aprend- é radical, e -e é vogal temática, e -m, desinência número-pessoal Está correto o que se afirma em","opcoes":["I, II, III e IV apenas.","I, II, III, IV e V.","III, IV e V apenas.","I, II e V apenas."],"correta":2,"explicacao":"Gabarito: <strong>III, IV e V apenas.</strong>.","banca":"UECE-CEV","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2156,"enunciado":"Em relação à estrutura das palavras, marcar C para as afirmativas Certas, E para as Erradas e, após, assinalar a alternativa que apresenta a sequência CORRETA: (---) As palavras mar, sol e ar não podem dividir-se em formas menores significativas porque só apresentam um elemento mórfico: o radical. (---) As desinências nominais marcam as flexões de número, pessoa, tempo e modo. (---) Tema é o radical acrescido da vogal temática.","opcoes":["C - C - C.","E - E - C.","E - C - E.","C - E - C."],"correta":3,"explicacao":"Gabarito: <strong>C - E - C.</strong>.","banca":"OBJETIVA","ano":2018,"temas_relacionados":["formacaoPalavras"]},{"id":2159,"enunciado":"O prefixo “in-”, geralmente, é anexado a uma palavra a fim de produzir um sentido de negação do seu significado, como ocorre em “inexpugnável” (linha 7). Esse sentido de negação NÃO está presente em","opcoes":["inalienável.","inexprimível.","intocável.","inaudível.","inflamável."],"correta":4,"explicacao":"Gabarito: <strong>inflamável.</strong>.","banca":"UFES","ano":2017,"temas_relacionados":["formacaoPalavras"]},{"id":2160,"enunciado":"Considere as seguintes afirmações sobre a palavra descentralizada (l. 38). I. Seu prefixo tem o mesmo sentido que o prefixo da palavra desrespeitado (l. 20). II. Seu sufixo forma adjetivos a partir de verbos. III. Ela significa o mesmo que descentrada. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"MPE-RS","ano":2015,"temas_relacionados":["formacaoPalavras"]},{"id":2161,"enunciado":"“Pois cada lembraNÇA brasileira corresponde à memória do mundo”. (3º §) “Criaturas que, afinadas com a torpEZA e as inquietudes do seu tempo”.(5º §) São sinônimos, respectivamente, dos sufixos em destaque nos vocábulos acima os sufixos empregados na formação das palavras","opcoes":["traição e banalidade.","advertência e mortuárias.","fumegante e alojamento.","sordidez e inquietudes.","alegria e brasileira."],"correta":0,"explicacao":"Gabarito: <strong>traição e banalidade.</strong>.","banca":"COSEAC","ano":2016,"temas_relacionados":["formacaoPalavras"]},{"id":2162,"enunciado":"No Texto 1, os termos “Caladona” e “Nespressão” são derivados, respectivamente, de “calar” e “Nespresso”, pelo seguinte processo de formação de palavras:","opcoes":["regressão.","sufixação.","justaposição.","aglutinação."],"correta":1,"explicacao":"Gabarito: <strong>sufixação.</strong>.","banca":"IV - UFG","ano":2017,"temas_relacionados":["formacaoPalavras"]},{"id":2163,"enunciado":"O par de palavras em que ocorre o fenômeno da derivação sufixal é:","opcoes":["“algumas” – “pequenas”.","“podem” – “detalhada”.","“microscópico” – “capacidade”.","“detalhada” – “capacidade”.","“vírus” – “diferenças”."],"correta":3,"explicacao":"Gabarito: <strong>“detalhada” – “capacidade”.</strong>.","banca":"Instituto Coelho Neto","ano":2016,"temas_relacionados":["formacaoPalavras"]},{"id":2164,"enunciado":"Analise as afirmações sobre a formação das palavras retiradas do texto: I - A palavra “sobressalto” é formada por justaposição assim como “girassol”. II - idêntico processo de formação de palavra está presente em “trabalho” e “alerta”. III - A palavra “inalterável” é formada por derivação parassintética. IV - O sufixo de “nevoeiro” da ideia de intensidade. Quais afirmativas estão corretas?","opcoes":["Apenas I e II.","Apenas II e IV.","Apenas I, III e IV.","II, III e IV."],"correta":1,"explicacao":"Gabarito: <strong>Apenas II e IV.</strong>.","banca":"EXATUS-PR","ano":2015,"temas_relacionados":["formacaoPalavras"]},{"id":2168,"enunciado":"Em relação à formação lexical da palavra ensolarado é correto dizer:","opcoes":["é um caso de parassintetismo;","é uma derivada prefixal e sufixal;","é uma derivada regressiva;","é um caso de derivação imprópria;","é uma onomatopeia."],"correta":0,"explicacao":"Gabarito: <strong>é um caso de parassintetismo;</strong>.","banca":"INAZ do Pará","ano":2016,"temas_relacionados":["formacaoPalavras"]},{"id":2169,"enunciado":"Os termos nanorrobôs, singularidade e empoderar apresentam, respectivamente, os processos de formação de palavras:","opcoes":["Prefixação, hibridismo, derivação regressiva.","Composição por justaposição, sufixação e parassíntese.","Composição por justaposição, sufixação e prefixação.","Prefixação, sufixação, parassíntese."],"correta":3,"explicacao":"Gabarito: <strong>Prefixação, sufixação, parassíntese.</strong>.","banca":"IF-MT","ano":2016,"temas_relacionados":["formacaoPalavras"]},{"id":2170,"enunciado":"O prefixo “im” pode indicar negação, como na palavra impunidade, que significa ausência de punição. O prefixo da seguinte palavra também indica negação:","opcoes":["transformação","desrespeito","prevenção","diálogo"],"correta":1,"explicacao":"Gabarito: <strong>desrespeito</strong>.","banca":"FUNRIO","ano":2016,"temas_relacionados":["formacaoPalavras"]},{"id":2173,"enunciado":"Assinale a alternativa em que a palavra extraída do texto NÃO apresenta, em sua formação, processo de derivação prefixal.","opcoes":["reequilíbrio (l. 07)","realmente (l. 20)","readquiria (l. 26)","reavaliado (l. 29)","reanimar (l. 37)"],"correta":1,"explicacao":"Gabarito: <strong>realmente (l. 20)</strong>.","banca":"FAURGS","ano":2016,"temas_relacionados":["formacaoPalavras"]},{"id":2176,"enunciado":"Das palavras abaixo, retiradas do cartum, assinale a única que permite desinência de gênero:","opcoes":["Brasil","Dinheiro","Necessitados","Mundo"],"correta":2,"explicacao":"Gabarito: <strong>Necessitados</strong>.","banca":"Crescer Concursos","ano":2017,"temas_relacionados":["formacaoPalavras"]},{"id":2177,"enunciado":"“Autoritários e populistas do passado davam uma banana para o custeio – e o controle de qualidade – da educação básica. Governos democráticos a partir de 1985 fizeram disparar a despesa. Muito da redução na desigualdade de renda se deve a isso.” A palavra desse segmento que não é formada com um sufixo é","opcoes":["autoritários.","controle.","populistas.","desigualdade.","educação."],"correta":1,"explicacao":"Gabarito: <strong>controle.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["formacaoPalavras"]},{"id":2179,"enunciado":"A palavra sustentabilidade tem em sua formação um:","opcoes":["Prefixo.","Sufixo.","Parassintético.","Neologismo."],"correta":1,"explicacao":"Gabarito: <strong>Sufixo.</strong>.","banca":"INAZ do Pará","ano":2019,"temas_relacionados":["formacaoPalavras"]},{"id":2180,"enunciado":"A palavra “ambiente”, utilizada no texto, é formada pelo prefixo de origem latina “ambi”, que, por sua vez, é indicativo de:","opcoes":["Anterioridade.","Superioridade.","Intensidade.","Proximidade.","Duplicidade."],"correta":4,"explicacao":"Gabarito: <strong>Duplicidade.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["formacaoPalavras"]},{"id":2181,"enunciado":"A significação do sufixo difere de “ação ou resultado dela” na palavra","opcoes":["segurança \\[-ança].","rendimento \\[-mento].","capacidade \\[-dade].","eliminação \\[-ção]."],"correta":2,"explicacao":"Gabarito: <strong>capacidade \\[-dade].</strong>.","banca":"UECE-CEV","ano":2019,"temas_relacionados":["formacaoPalavras"]},{"id":2182,"enunciado":"O termo “hipermoderno” (l. 30) é formado pelo prefixo grego “hiper”, que, por sua vez, é indicativo de:","opcoes":["Proximidade.","Superioridade.","Anterioridade.","Simultaneidade.","Bondade."],"correta":1,"explicacao":"Gabarito: <strong>Superioridade.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["formacaoPalavras"]},{"id":2184,"enunciado":"Acerca dos sufixos, é possível afirmar que:","opcoes":["Os sufixos são unidades mínimas da palavra que, isoladamente, possuem um significado.","Os sufixos são um morfema que, quando acrescentados a um radical, formam uma nova palavra.","Os sufixos, assim como os prefixos, são afixos incapazes de transformar a classe gramatical de uma palavra.","Na língua portuguesa, apenas o processo de derivação sufixal se utiliza dos sufixos para a formação de palavras."],"correta":1,"explicacao":"Gabarito: <strong>Os sufixos são um morfema que, quando acrescentados a um radical, formam uma nova palavra.</strong>.","banca":"AGIRH","ano":2020,"temas_relacionados":["formacaoPalavras"]},{"id":2185,"enunciado":"Quanto aos elementos estruturais da palavra, marque a alternativa incorreta.","opcoes":["Morfemas são as menores unidades significativas que se combinam para formar as palavras.","Radical é o morfema que contém o significado básico do vocábulo e a partir do qual é possível constituir uma família de palavras.","Os sufixos se posicionam antes do radical e os prefixos se posicionam depois do radical.","Desinências são elementos que se juntam à parte final de certas palavras para caracterizar suas flexões, isto é, as variações de forma."],"correta":2,"explicacao":"Gabarito: <strong>Os sufixos se posicionam antes do radical e os prefixos se posicionam depois do radical.</strong>.","banca":"MSConcursos","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2186,"enunciado":"Sobre a estrutura e o processo de formação das palavras da língua portuguesa, assinale o que for correto.","opcoes":["As palavras enterrar e azulejar são formadas pelo mesmo processo de derivação sufixal.","Planalto e embora são formadas por composição por justaposição.","As palavras pedra, pedreira, apedrejar e petrificado apresentam o mesmo radical, ou seja, PEDRA.","Em combate e dança temos uma derivação regressiva ou deverbal.","As palavras amanhã, manhã e amanhecer apresentam o mesmo radical, sendo chamadas, portanto, de cognatas."],"correta":3,"explicacao":"Gabarito: <strong>Em combate e dança temos uma derivação regressiva ou deverbal.</strong>.","banca":"EPL Concursos","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2187,"enunciado":"Considerando a palavra “ultrapassada”, analise as assertivas a seguir: I. A palavra foi formada por derivação prefixal, com a adição do prefixo “ultra-“ ao adjetivo “passada”. II. O significado da adição desse prefixo resulta em “extremamente passada”. Assinale a alternativa correta a respeito das assertivas anteriores.","opcoes":["As duas assertivas são verdadeiras.","As duas assertivas são falsas.","A primeira assertiva é verdadeira e a segunda, falsa.","A primeira assertiva é falsa e a segunda, verdadeira."],"correta":0,"explicacao":"Gabarito: <strong>As duas assertivas são verdadeiras.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2190,"enunciado":"Assinale a alternativa que preenche corretamente a lacuna pontilhada na primeira frase do texto.","opcoes":["prefixo grego","prefixo latino","sufixo nominal","sufixo adverbial","sufixo verbal"],"correta":2,"explicacao":"Gabarito: <strong>sufixo nominal</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2192,"enunciado":"Sobre as palavras retiradas do texto, analise as assertivas abaixo: I. Na palavra “impedir”, “i”, que está em negrito, é vogal temática. II. A palavra “discriminação” apresenta somente sufixo. III. Em “ofensivo”, “o”, que está em negrito, é a desinência de gênero. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2193,"enunciado":"Sobre as palavras retiradas do texto, considere as seguintes afirmações: I. A palavra “subsequentes” apresenta prefixo. II. A palavra “especialmente” apresenta prefixo e sufixo. III. Em “vacinas”, “s” é a desinência de número. Quais estão corretas?","opcoes":["Apenas I.","Apenas I e II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>Apenas I e III.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2194,"enunciado":"Sobre as seguintes palavras retiradas do texto, analise as assertivas abaixo: I. A palavra “individuais” apresenta o prefixo ‘in-’. II. O radical da palavra “trabalhista” é ‘trabalh’. III. A palavra “necessidades” não apresenta sufixo. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas II e III.","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>Apenas II.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":2197,"enunciado":"Assinale a alternativa que apresenta palavra com prefixo.","opcoes":["Antidiurético.","Identificar.","Importante.","Irritabilidade.","Rigorosamente."],"correta":0,"explicacao":"Gabarito: <strong>Antidiurético.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2198,"enunciado":"Quais são, respectivamente, os sentidos veiculados pelos prefixos das palavras “prenunciavam” (3º parágrafo) e “sobrevivência” (5º parágrafo)?","opcoes":["Posterioridade e superioridade.","Superioridade e inferioridade.","Inferioridade e anterioridade.","Anterioridade e posterioridade."],"correta":3,"explicacao":"Gabarito: <strong>Anterioridade e posterioridade.</strong>.","banca":"ADM\\&TEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2201,"enunciado":"Assinale a alternativa que apresenta palavra formada somente pelo processo de sufixação, assim como o vocábulo “emblemático”.","opcoes":["Queixa.","Imóvel.","Acéfalo.","Arvoredo.","Imutável."],"correta":3,"explicacao":"Gabarito: <strong>Arvoredo.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2202,"enunciado":"Nas palavras a seguir, retiradas do texto, verificam-se diferentes afixos que indicam processos derivacionais e flexionais de formação. Assinale a alternativa em que todas as palavras apresentam sufixo formador de adjetivos na língua portuguesa.","opcoes":["inundação; novamente; figuras.","divindades; inscrições; pesquisadores.","astronômicas; invisível; egípcias.","particularidades; especialistas; diferentes.","zodíaco; aproximadamente; restauração."],"correta":2,"explicacao":"Gabarito: <strong>astronômicas; invisível; egípcias.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2205,"enunciado":"A palavra “infindáveis” foi formada a partir da junção do prefixo in- ao vocábulo “findáveis”, conferindo a ela um sentido negativo. Assinale a alternativa que apresenta palavra formada pela adição do mesmo prefixo e com o mesmo significado.","opcoes":["Inveja.","Íntimo.","Interior.","Invariável.","Intriga."],"correta":3,"explicacao":"Gabarito: <strong>Invariável.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2206,"enunciado":"Considere o excerto a seguir para responder às questões 7 e 8: É esperado: ao tocar piano, você está inconscientemente prestando atenção na harmonia e tempo entre as notas, além de cautelosamente avaliar a posição das suas mãos e de seus dedos. O significado do sufixo que ocorre em “inconscientemente” e “cautelosamente” está relacionado à expressão de:","opcoes":["intensidade.","lugar.","negação.","modo.","quantidade."],"correta":3,"explicacao":"Gabarito: <strong>modo.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2209,"enunciado":"Assinale a alternativa que apresenta adequadamente o radical da palavra “redescoberta”.","opcoes":["re","redes","cob","erta"],"correta":2,"explicacao":"Gabarito: <strong>cob</strong>.","banca":"ADM\\&TEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2211,"enunciado":"Assinale a alternativa que apresenta, uma palavra com sufixo e outra com prefixo, respectivamente:","opcoes":["Formosura – orfanato.","Antivírus – abdicar.","Paredão – riacho.","Folhear – hipertensão.","Antipatia – prólogo."],"correta":3,"explicacao":"Gabarito: <strong>Folhear – hipertensão.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2212,"enunciado":"Assinale a alternativa em que uma das palavras não é formada por prefixação.","opcoes":["Abdicar — conjurar — dissidente.","Periferia — introverter — anarquia.","Dever — deter — antever.","Incômodo — imigrar — traspassar."],"correta":2,"explicacao":"Gabarito: <strong>Dever — deter — antever.</strong>.","banca":"ADM\\&TEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2213,"enunciado":"A partir do verbo PUBLICAR, obtém-se PUBLICAÇÃO, que é uma palavra derivada. O elemento destacado é classificado como:","opcoes":["vogal temática","radical","prefixo","sufixo"],"correta":3,"explicacao":"Gabarito: <strong>sufixo</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2214,"enunciado":"Assinale a alternativa que apresente palavra que possua prefixo:","opcoes":["Eliminado.","Liberado.","Depositantes.","Acelerando.","Inesperadas."],"correta":4,"explicacao":"Gabarito: <strong>Inesperadas.</strong>.","banca":"FAU","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2216,"enunciado":"Assinalar a alternativa que apresenta uma frase em que o prefixo sublinhado tem sentido de simultaneidade:","opcoes":["Ele não tem muita simpatia pela chefe.","Vamos desenhar um semicírculo.","João abdicou do trono.","Todos precisam cuidar da hipertensão arterial."],"correta":0,"explicacao":"Gabarito: <strong>Ele não tem muita simpatia pela chefe.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2218,"enunciado":"Julgue o item subsequente.\nPara formar novas palavras, um dos processos mais comuns é a derivação prefixal, que consiste em adicionar um prefixo ao final da palavra-base, alterando seu significado original.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2220,"enunciado":"Julgue o item subsequente.\nA palavra \"moto\", uma abreviação de \"motocicleta\", exemplifica como a abreviação vocabular pode ser utilizada para simplificar a comunicação, criando termos mais curtos e práticos a partir de palavras mais longas.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2221,"enunciado":"O grupo em que todas as palavras apresentam prefixo que expressa negação é","opcoes":["desconfiança, inferioridade, invasão","descrença, inconveniência, impaciência","desenvolvimento, descrição, infelicidade","desigualdade, indústria, infecção","despeito, descendência, imoralidade"],"correta":1,"explicacao":"Gabarito: <strong>descrença, inconveniência, impaciência</strong>.","banca":"CESGRANRIO","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2222,"enunciado":"Assinale a alternativa que apresenta adequadamente o radical da palavra “redescoberta”.","opcoes":["re.","redes.","descobr.","coberta."],"correta":2,"explicacao":"Gabarito: <strong>descobr.</strong>.","banca":"ADM\\&TEC","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2223,"enunciado":"Assinale a única alternativa em que o elemento destacado é um prefixo","opcoes":["Interessadas (linha 20)","Importantes (linha 19)","Italiano (linha 15)","Imigrou (linha 15)"],"correta":3,"explicacao":"Gabarito: <strong>Imigrou (linha 15)</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":2225,"enunciado":"Assinale a alternativa cuja palavra NÃO possua sufixo:","opcoes":["Registrada.","Histórica.","Brasileiros.","Estados.","Federação."],"correta":3,"explicacao":"Gabarito: <strong>Estados.</strong>.","banca":"FAU","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2226,"enunciado":"Assinale a alternativa que apresenta, respectivamente, uma palavra derivada por prefixação e outra derivada por sufixação:","opcoes":["“desordem” | “calmaria”","“correria” | “anormal”","“orgulhoso” | “prataria”","“apedrejar” | “adormecer”.","“pizzaria” | “restaurante”."],"correta":0,"explicacao":"Gabarito: <strong>“desordem” | “calmaria”</strong>.","banca":"FUNCEPE","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2227,"enunciado":"Sobre o termo “Peculando” observe as proposições a seguir. I. Derivação Imprópria - apresenta verbo a partir de substantivo. II. Derivação Sufixal - apresenta sufixo formador verbo a partir de adjetivo. III. Derivação Imprópria, de substantivo a um verbo. IV. Derivação Sufixal - apresenta sufixo formador de gerúndio. Quais as afirmações que estão CORRETAS?","opcoes":["I.","II.","III.","IV.","I – IV."],"correta":3,"explicacao":"Gabarito: <strong>IV.</strong>.","banca":"FUNCEPE","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2228,"enunciado":"A palavra \"deboísmo\" é um neologismo, pois é uma palavra inventada, que não consta no dicionário. Ela foi formada a partir do processo indicado na opção.","opcoes":["Derivação imprópria: mudança de classe gramatical, de adjetivo a substantivo.","Derivação parassintética: acréscimo de prefixo e de sufixo ao mesmo tempo.","Composição por aglutinação: locução “de boa” mais termo cristianismo.","Derivação sufixal: sufixo-ismo à expressão \"de boa\".","Composição por justaposição: união de dois radicais."],"correta":3,"explicacao":"Gabarito: <strong>Derivação sufixal: sufixo-ismo à expressão \"de boa\".</strong>.","banca":"FUNCEPE","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2229,"enunciado":"Sobre o título do texto, analise as informações: I- A palavra escutatória é um neologismo, com sentido de habilidade de desenvolvimento do processo de escuta ativa. II- Derivada do verbo escutar, a palavra escutatória é o antônimo de falatório. III- O termo escutatória passou por um processo de formação de palavras: a derivação sufixal. É CORRETO o que se afirma em:","opcoes":["I apenas.","II apenas.","I e III apenas.","III apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>I e III apenas.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":2959,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir.\nNo excerto “A relação entre terapeuta e paciente desenvolve‑se a partir do estabelecimento de micro‑objetivos definidos em conjunto, criando um ambiente de corresponsabilidade e estímulo que fortalece o processo terapêutico.”, os termos “micro‑objetivos” e “corresponsabilidade” seguem as mesmas regras para emprego ou não aplicação do hífen, pois possuem prefixos de mesma origem.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras","hifen"]},{"id":3119,"enunciado":"Julgue o seguinte item, relativo às ideias e às construções linguísticas do texto anterior. No trecho \"Lucas disse ter se encontrado\" (último período do segundo parágrafo), a partícula \"se\" poderia ser conectada ao verbo auxiliar mediante hífen, escrevendo-se ter-se encontrado, sem prejuízo da correção gramatical do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras","hifen"]},{"id":3120,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir. No período “uma voz que se torna diferente do habitual pode ser um indicativo de que algo não vai bem”, a substituição de “se torna” por a torna preservaria tanto a correção gramatical quanto o sentido original do texto, mantendo a próclise devido à partícula atrativa “que”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":3505,"enunciado":"Estaria mantida a correção gramatical do quarto período do primeiro parágrafo caso a partícula “se”, em “verifica-se”, fosse deslocada para a posição proclítica — se verifica.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":3693,"enunciado":"A respeito de aspectos gramaticais do texto CB3A1-II, julgue o item subsequente. No trecho “a par do que se trata” (terceiro parágrafo), a anteposição da partícula “se” ao verbo justifica-se pela presença do vocábulo “que”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":3862,"enunciado":"Ciente de que o seu primeiro leitor era o professor, a aluna fez a redação com base na imagem que cria do “gosto” e da visão de língua do professor. São marcas linguísticas desse destinatário virtual","opcoes":["o sufixo flexional, que marca a flexão de grau em “bacaninha”.","o uso do prefixo separado por hífen, devido a reforma ortográfica, em“ultra-silencioso”.","a pronominalização de formas verbais como em “desejo-lhe”","a derivação regressiva ao usar a palavra “tv”.","o sufixo –eco, diminutivo, em “amoreco”."],"correta":2,"explicacao":"Gabarito: <strong>a pronominalização de formas verbais como em “desejo-lhe”</strong>.","banca":"LJ Assessoria e Planejamento Administrativo Limita","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":3972,"enunciado":"\"Segundo o Ibama (Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renováveis), o monitoramento das araras identificou um casal passando longos períodos em ninhos projetados pelos pesquisadores do Projeto de Reintrodução da Arara-vermelha-grande na Mata Atlântica.\"Considerando o valor semântico que as palavras assumem no contexto, assinale a alternativa incorreta.","opcoes":["O vocábulo 'ninhos' é empregado em sentido denotativo, entretanto, em 'aquele apartamento era o nosso ninho', o mesmo vocábulo assume sentido conotativo, evocando ideia de aconchego, proteção e intimidade familiar.","O vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.","O vocábulo 'longos' é empregado no trecho em sentido denotativo, indicando extensão temporal mensurável dos períodos em que o casal permanecia nos ninhos, sem qualquer carga subjetiva ou figurada.","O vocábulo 'projetados' é empregado no trecho em sentido denotativo de 'planejados' e 'construídos', mas em 'seus sonhos eram projetados para um futuro distante' assume sentido conotativo, indicando expectativa e idealização."],"correta":1,"explicacao":"Gabarito: <strong>O vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":3975,"enunciado":"\"Segundo o Ibama (Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renováveis), o monitoramento das araras identificou um casal passando longos períodos em ninhos projetados pelos pesquisadores do Projeto de Reintrodução da Arara-vermelha-grande na Mata Atlântica.\"Considerando o valor semântico que as palavras assumem no contexto, assinale a alternativa incorreta.","opcoes":["O vocábulo 'longos' é empregado no trecho em sentido denotativo, indicando extensão temporal mensurável dos períodos em que o casal permanecia nos ninhos, sem qualquer carga subjetiva ou figurada.","vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.","O vocábulo 'projetados' é empregado no trecho em sentido denotativo de 'planejados' e 'construídos', mas em 'seus sonhos eram projetados para um futuro distante' assume sentido conotativo, indicando expectativa e idealização.","O vocábulo 'ninhos' é empregado em sentido denotativo, entretanto, em 'aquele apartamento era o nosso ninho', o mesmo vocábulo assume sentido conotativo, evocando ideia de aconchego, proteção e intimidade familiar."],"correta":1,"explicacao":"Gabarito: <strong>vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":4052,"enunciado":"Considerando o processo de formação e à classificação morfológica da palavra \"canto\" no enunciado \"Era o canto mais lindo que alguém já ouvira em todo o universo\", pode-se afirmar que trata-se de um substantivo:","opcoes":["formado por derivação regressiva, pois deriva-se da forma verbal \"cantar\" com supressão de morfema.","primitivo, não derivado de outro vocábulo da língua portuguesa.","originado por derivação imprópria a partir do verbo \"cantar\", com mudança de classe sem alteração estrutural.","construído por derivação sufixal, com o acréscimo do sufixo nominal \"-o\" ao radical \"cant-\"."],"correta":0,"explicacao":"Gabarito: <strong>formado por derivação regressiva, pois deriva-se da forma verbal \"cantar\" com supressão de morfema.</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":4053,"enunciado":"Considerando o processo de formação e à classificação morfológica da palavra \"canto\" no enunciado \"Era o canto mais lindo que alguém já ouvira em todo o universo\", pode-se afirmar que trata-se de um substantivo:","opcoes":["construído por derivação sufixal, com o acréscimo do sufixo nominal \"-o\" ao radical \"cant-\".","primitivo, não derivado de outro vocábulo da língua portuguesa.","originado por derivação imprópria a partir do verbo \"cantar\", com mudança de classe sem alteração estrutural.","formado por derivação regressiva, pois deriva-se da forma verbal \"cantar\" com supressão de morfema"],"correta":3,"explicacao":"Gabarito: <strong>formado por derivação regressiva, pois deriva-se da forma verbal \"cantar\" com supressão de morfema</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":4444,"enunciado":"A partícula “que” (linha 14) introduz uma oração subordinada:","opcoes":["substantiva completiva nominal.","substantiva objetiva direta.","substantiva predicativa.","adjetiva restritiva.","adjetiva explicativa."],"correta":1,"explicacao":"Gabarito: <strong>substantiva objetiva direta.</strong>.","banca":"ADVISE","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":4621,"enunciado":"Na formação da palavra “reconhecimento”, observa-se o elemento inicial “re-“, denominado prefixo, que pode significar “movimento para trás, repetição, reciprocidade, intensidade”. Considerando o estágio atual da Língua Portuguesa, indique, dentre as opções abaixo, o substantivo que contém esse prefixo.","opcoes":["Relação","Recentemente","Regulamentação","Regramentos","Reintegração"],"correta":4,"explicacao":"Gabarito: <strong>Reintegração</strong>.","banca":"COSEAC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":4667,"enunciado":"Assinale a opção que indica o par de palavras em que o A final é identificado como desinência de gênero.","opcoes":["alma / aluna.","gata / bonita.","máquina / casa.","ela / cadela.","estranha / colcha."],"correta":1,"explicacao":"Gabarito: <strong>gata / bonita.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":4992,"enunciado":"Considerando o texto “Cuidado! Bebidas energéticas podem desencadear arritmias cardíacas graves”, assinale a alternativa que contém um trecho com linguagem coloquial:","opcoes":["A composição de um energético inclui taurina, guaraná e outros ingredientes estimulantes.","Aliás, nesse ritmo acelerado, já nem bate - tremelica.","A maioria era mulher - seis das vítimas.","podem desenvolver uma extrassístole depois de sorver uma dose de energético."],"correta":1,"explicacao":"Gabarito: <strong>Aliás, nesse ritmo acelerado, já nem bate - tremelica.</strong>.","banca":"Prefeitura de Bauru - SP","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":5079,"enunciado":"Analise as palavras compostas “quinta-feira”, “Pastor-de-shetland” e “bem-estar”, que ocorrem no texto. Aquela(s) em que, quando pluralizada(s), apenas o último elemento varia é (são):","opcoes":["quinta-feira.","Pastor-de-shetland.","bem-estar.","quinta-feira e bem-estar.","Pastor-de-shetland e quinta-feira."],"correta":2,"explicacao":"Gabarito: <strong>bem-estar.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":5215,"enunciado":"Julgue o item subsequente.A palavra \"reajustamento\" exemplifica um processo morfológico de derivação regressiva, no qual o sufixo \"mento\" é adicionado ao verbo \"reajustar\", para formar um substantivo abstrato.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":5313,"enunciado":"Na palavra REDES, o elemento mórfico destacado cumpre o mesmo papel atestado em:","opcoes":["lápis","ônibus","empresas","merecestes"],"correta":2,"explicacao":"Gabarito: <strong>empresas</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":5521,"enunciado":"A troca da partícula muda o sentido em:","opcoes":["\"( ... ) a repugnância aos pobres ( ... )\" (aos dos).","\"( ... ) subjacentes a muitos ( ... )\" (a - em).","\"( ... ) para dar visibilidade ( ... )\" (para - a fim de).","\"( ... ) sendo usada em vários artigos ( ... )\" (em por)."],"correta":0,"explicacao":"Gabarito: <strong>\"( ... ) a repugnância aos pobres ( ... )\" (aos dos).</strong>.","banca":"Fundação CETAP","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":5639,"enunciado":"“Dá-se o nome de artigo às palavras o (com as variações a, os, as) e um (com as variações uma, uns, umas), que se antepõem aos substantivos para indicar que se trata de um ser já conhecido do leitor ou que se trata de um simples representante de uma dada espécie.” CUNHA, Celso e CINTRA, Lindley. Nova Gramática do Português Contemporâneo. Editora: Lexikon; 7ª edição; p. 199. Essa definição da classe dos artigos se fundamenta nos seguintes critérios:","opcoes":["morfológico e sintático.","sintático e semântico.","morfológico e semântico.","morfológico, sintático e semântico.","morfológico, sintático, semântico e fonológico."],"correta":3,"explicacao":"Gabarito: <strong>morfológico, sintático e semântico.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":5680,"enunciado":"Em “[...] mostra que as propriedades dessa toxina se estendem aos tratamentos emocionais.” (segundo texto – 2º§). Assinale a afirmativa em que o “as” apresenta valor morfológico distinto do “as” destacado no fragmento anterior.","opcoes":["“[...] 40 mil pessoas que receberam as injeções por oito motivos diferentes.” (3º§)","“[...] as pessoas que receberam as aplicações tinham uma diminuição do risco [...]” (3º§)","“[...] quando aplicado entre as sobrancelhas, o produto tem ações antidepressivas.” (2º§)","“[...] tratamento de dores de cabeça severas, como as provocadas pela enxaqueca, [...]” (1º§)"],"correta":3,"explicacao":"Gabarito: <strong>“[...] tratamento de dores de cabeça severas, como as provocadas pela enxaqueca, [...]” (1º§)</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["formacaoPalavras"]},{"id":5731,"enunciado":"“O lexema, ou morfema lexical, é um tipo de palavra que contém informação básica de significado que representa o mundo extralinguístico ou remete a ele. Chamamos esse \"mundo extralinguístico\" de mundo biossocial/antropocultural, pois representa aquilo que se poderia definir como \"o ser humano e a sua cultura na vida em sociedade\". Já com o gramema, ou morfema gramatical, o mesmo não ocorre. Há outro conjunto de palavras na língua que remete exclusivamente a um mundo gramatical (apenas linguístico) e é restrito à função de apenas relacionar ou de estruturar as palavras. O falante conhece essas palavras, sabe que pertencem à língua portuguesa, mas elas não têm carga semântica representativa.” (SAUTCHUK, 2010, p. 6-7) As palavras que representam um lexema e um gramema, respectivamente, são","opcoes":["“chorar” e “rir”.","“pesado” e “sol”.","“essa” e “verde”.","“árvore” e “uma”.","“nossa” e “algum”."],"correta":3,"explicacao":"Gabarito: <strong>“árvore” e “uma”.</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":5844,"enunciado":"Considerando o item destacado em “[...] com a chegada do primeiro choque do petróleo [...]”, assinale a alternativa correta.","opcoes":["Trata-se de um numeral cardinal.","Pertence à classe morfológica dos artigos quantificadores.","É a marca linguística que permite o seguinte pressuposto: houve mais que um choque do petróleo.","É a marca linguística que permite a seguinte conclusão: houve muitos choques do petróleo.","É a marca linguística que permite ao leitor identificar a ironia no excerto."],"correta":2,"explicacao":"Gabarito: <strong>É a marca linguística que permite o seguinte pressuposto: houve mais que um choque do petróleo.</strong>.","banca":"INSTITUTO AOCP","ano":2022,"temas_relacionados":["formacaoPalavras"]},{"id":5881,"enunciado":"A partícula “que” empregada na linha 16 do Texto poderia ser CORRETAMENTE substituída pela seguinte alternativa:","opcoes":["“no qual”;","“o qual”;","“em que”;","“a qual”;","“para o qual”."],"correta":1,"explicacao":"Gabarito: <strong>“o qual”;</strong>.","banca":"ADVISE","ano":2021,"temas_relacionados":["formacaoPalavras"]},{"id":6006,"enunciado":"Sobre os mecanismos linguísticos usados no texto, é correto afirmar o que se afirma em","opcoes":["“tantos’ (L.49) expressa valor numérico.","“O” em “O que permanece” (L.61) e “O”, em “O restante é passageiro e ilusório” (L.62) têm o mesmo valor morfológico.","Em “vive-se dessa maneira” (L.37), o vocábulo “se” é marca de indeterminação do sujeito.","“A expressão “exemplos” (L.55) continuará exercendo a mesma função sintática se o verbo existir, presente no contexto em que se encontra, for substituído pelo verbo haver,"],"correta":2,"explicacao":"Gabarito: <strong>Em “vive-se dessa maneira” (L.37), o vocábulo “se” é marca de indeterminação do sujeito.</strong>.","banca":"Crescer Concursos","ano":2019,"temas_relacionados":["formacaoPalavras"]},{"id":6010,"enunciado":"Sobre os recursos linguísticos usados no texto, é CORRETO afirmar:","opcoes":["Os conectores “que” e “que”, em “Estudos apontam que a sociedade atual” (L.5), e, em “o importante é o que você tem” (L.11), são iguais do ponto de vista morfológico.","Os vocábulos “o” e “o”, em “onde o importante é o que você tem e não que você é,” (L.11) possuem o mesmo valor morfológico.","A expressão “relação” (L.7) mudará de função sintática caso haja a substituição do verbo “haver” pela forma verbal correlata “existir”.","A expressão “da natureza” (L.8) complementa o sentido de um verbo, na função de objeto indireto."],"correta":2,"explicacao":"Gabarito: <strong>A expressão “relação” (L.7) mudará de função sintática caso haja a substituição do verbo “haver” pela forma verbal correlata “existir”.</strong>.","banca":"IMA","ano":2019,"temas_relacionados":["formacaoPalavras"]},{"id":6117,"enunciado":"A classificação morfológica do vocábulo “a” em “boa parte da população brasileira tem acesso a redes sociais” SÓ NÃO se repete em:","opcoes":["“Quando a pessoa recebe uma notícia que a agrada” [...].","“Isso impulsiona a pessoa a transmitir compulsivamente” [...].","“O ser humano tem essa tendência a buscar essas crenças, mágicas.”","“A gente precisa se organizar para se adequar a esse mundo digital.”"],"correta":0,"explicacao":"Gabarito: <strong>“Quando a pessoa recebe uma notícia que a agrada” [...].</strong>.","banca":"IBGP","ano":2018,"temas_relacionados":["formacaoPalavras"]},{"id":6297,"enunciado":"\"Segundo o Ibama (Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renováveis), o monitoramento das araras identificou um casal passando longos períodos em ninhos projetados pelos pesquisadores do Projeto de Reintrodução da Arara-vermelha-grande na Mata Atlântica.\" Considerando o valor semântico que as palavras assumem no contexto, assinale a alternativa incorreta.","opcoes":["O vocábulo 'ninhos' é empregado em sentido denotativo, entretanto, em 'aquele apartamento era o nosso ninho', o mesmo vocábulo assume sentido conotativo, evocando ideia de aconchego, proteção e intimidade familiar.","O vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.","O vocábulo 'longos' é empregado no trecho em sentido denotativo, indicando extensão temporal mensurável dos períodos em que o casal permanecia nos ninhos, sem qualquer carga subjetiva ou figurada.","O vocábulo 'projetados' é empregado no trecho em sentido denotativo de 'planejados' e 'construídos', mas em 'seus sonhos eram projetados para um futuro distante' assume sentido conotativo, indicando expectativa e idealização."],"correta":1,"explicacao":"Gabarito: <strong>O vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":6300,"enunciado":"\"Segundo o Ibama (Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renováveis), o monitoramento das araras identificou um casal passando longos períodos em ninhos projetados pelos pesquisadores do Projeto de Reintrodução da Arara-vermelha-grande na Mata Atlântica.\" Considerando o valor semântico que as palavras assumem no contexto, assinale a alternativa incorreta.","opcoes":["O vocábulo 'longos' é empregado no trecho em sentido denotativo, indicando extensão temporal mensurável dos períodos em que o casal permanecia nos ninhos, sem qualquer carga subjetiva ou figurada.","vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.","O vocábulo 'projetados' é empregado no trecho em sentido denotativo de 'planejados' e 'construídos', mas em 'seus sonhos eram projetados para um futuro distante' assume sentido conotativo, indicando expectativa e idealização.","O vocábulo 'ninhos' é empregado em sentido denotativo, entretanto, em 'aquele apartamento era o nosso ninho', o mesmo vocábulo assume sentido conotativo, evocando ideia de aconchego, proteção e intimidade familiar."],"correta":1,"explicacao":"Gabarito: <strong>vocábulo 'casal' é empregado em sentido conotativo, pois sua aplicação ao universo animal representa uma transferência metafórica do campo semântico humano para o animal, não sendo possível seu uso denotativo fora do contexto das relações humanas.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":6781,"enunciado":"No trecho “[...] se podia utilizar-se do dinheiro que achara” (12º§), a transposição do termo em destaque para a voz passiva analítica, mantendo a estrita correspondência morfológica, resulta em:","opcoes":["[...] que se achara.","[...] que foi achado.","[...] que fora achado.","[...] que tinha sido achado."],"correta":2,"explicacao":"Gabarito: <strong>[...] que fora achado.</strong>.","banca":"Instituto Consulplan","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":6839,"enunciado":"Com base na composição da escolha vocabular e as intenções comunicativas do autor, aponte a alternativa com a informação correta sobre o texto:","opcoes":["O texto é predominantemente conotativo.","A composição verbal é de maioria subjuntiva.","A baixa ocorrência de figuras de linguagem agrega uma linguagem formal ao texto.","O texto trata de forma implícita da fiscalização da ONU a respeito das guerras."],"correta":2,"explicacao":"Gabarito: <strong>A baixa ocorrência de figuras de linguagem agrega uma linguagem formal ao texto.</strong>.","banca":"ABCP","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":6840,"enunciado":"É correto afirmar que no período “’Não podemos esquecer que se trata de uma doença relevante,’ [...]” (2º§):","opcoes":["O sujeito é simples.","O núcleo do predicado é formado pelo verbo “esquecer”.","O sujeito pode ser identificado através da desinência verbal.","O fragmento “que se trata de uma doença relevante” compõe o predicado."],"correta":2,"explicacao":"Gabarito: <strong>O sujeito pode ser identificado através da desinência verbal.</strong>.","banca":"Instituto Consulplan","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":6930,"enunciado":"Assinale a opção em que o valor semântico dos termos em destaque está correto.","opcoes":["“Um amigo que sumiu de vez do meu radar.” (§ 1°) - intensidade / lugar.","“[...] demarcam com precisão as diferenças entre o antes e o agora.” (§3°) - companhia / tempo.","“Um dia, ela me verá com o rosto completamente craquelado, miúda, corcunda pelo peso dos anos transcorridos, [...]”. (§4°) - modo / causa.","“Outro dia, mostrei para minha filha uma foto de nós duas em 1992; eu a segurava em meu colo.” (§3°) -finalidade / posse.","“Mesmo o mais implacável dos espelhos reflete algo em nós que não muda.” (§6°) - posse / lugar."],"correta":2,"explicacao":"Gabarito: <strong>“Um dia, ela me verá com o rosto completamente craquelado, miúda, corcunda pelo peso dos anos transcorridos, [...]”. (§4°) - modo / causa.</strong>.","banca":"Marinha","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":6977,"enunciado":"Assinale a alternativa que se refere de modo CORRETO a aspecto morfológico ou sintático que o texto apresenta:","opcoes":["Em “Houve uma troca de bebês no berçário”, o núcleo do sujeito é “troca”.","O “se”, em “Ele pergunta se foi tudo bem”, é uma partícula expletiva ou de realce.","O verbo “ir”, em “ele fora viver com seus verdadeiros pais”, deveria estar empregado no pretérito perfeito do indicativo.","O vocábulo “que”, em “que nunca entenderam o fato de terem um filho claro”, exerce a função de sujeito.","São advérbios, dentre outras, as seguintes palavras: “nunca”, “não”, “comigo” e “ainda”."],"correta":3,"explicacao":"Gabarito: <strong>O vocábulo “que”, em “que nunca entenderam o fato de terem um filho claro”, exerce a função de sujeito.</strong>.","banca":"COMVEST UFAM","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":7241,"enunciado":"O vocábulo destacado no verso “- que o clamor dos homens gloriosos” (v.7) introduz o valor semântico de:","opcoes":["comparação.","concessão.","oposição.","explicação.","conclusão."],"correta":3,"explicacao":"Gabarito: <strong>explicação.</strong>.","banca":"IBFC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":7307,"enunciado":"Nos enunciados: “Embora muitos alimentos ultraprocessados [...] possam satisfazer o desejo por alimentos doces, gordurosos e salgados, pesquisas sugerem que são particularmente ruins para o cérebro [...].” e “Porém, na natureza, os alimentos são modestamente ricos em açúcar [...] ou ricos em gordura, [...].”, o valor semântico dos termos destacados são, respectivamente:","opcoes":["Causa e explicação.","Concessão e oposição.","Proporcionalidade e oposição.","Concessão e adição."],"correta":1,"explicacao":"Gabarito: <strong>Concessão e oposição.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["formacaoPalavras"]},{"id":7615,"enunciado":"Na frase, ‘‘Varrendo a sala, não encontrou nada’’, a forma nominal no gerúndio exprime valor semântico de:","opcoes":["tempo.","modo.","causa.","consequência."],"correta":0,"explicacao":"Gabarito: <strong>tempo.</strong>.","banca":"Grupo TALENT","ano":2026,"temas_relacionados":["formacaoPalavras"]},{"id":7694,"enunciado":"Ao analisar a estrutura das palavras destacadas no trecho “Almejam-se o aumento da pena e o endurecimento das condições de cumprimento da pena” (5º parágrafo), em todas o sufixo expressa o sentido de:","opcoes":["favorecimento de uma ideia","desenvolvimento de uma ação","desdobramento de um conceito","questionamento de uma norma"],"correta":1,"explicacao":"Gabarito: <strong>desenvolvimento de uma ação</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":7702,"enunciado":"Texto 9 À PROCURA da felicidade. Direção de Gabriele Muccino. Estados Unidos: Sony Pictures, 2006. Com base no texto 9 e na variedade padrão da língua escrita, assinale a alternativa correta.","opcoes":["A palavra “possivelmente” (linhas 02, 05 e 08) descreve uma chance menor de que algo aconteça do que “provavelmente”.","O sufixo “-mente” acrescenta a ideia de gradação às palavras “possível” e “provável”.","A palavra “provavelmente” (linhas 04, 05 e 06) pode ser substituída por “obviamente”, mantendo o mesmo sentido do texto.","A palavra “possivelmente” (linhas 02, 05 e 08) indica certeza de não realização do evento.","Ambos os personagens associam à palavra “possivelmente” (linhas 02, 05 e 08) o significado de “provavelmente”."],"correta":0,"explicacao":"Gabarito: <strong>A palavra “possivelmente” (linhas 02, 05 e 08) descreve uma chance menor de que algo aconteça do que “provavelmente”.</strong>.","banca":"UFSC","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":7758,"enunciado":"“Ademais, a baixa valorização da leitura e da cultura do estudo em muitos contextos familiares e comunitários contribuem para a desmotivação dos estudantes”. Considerando o trecho destacado acima, marque a alternativa INCORRETA.","opcoes":["O termo “Ademais” é um advérbio que acrescenta uma ideia já apresentada anteriormente, podendo ser substituído por “além do mais”.","Após as palavras “estudo” e “comunitários”, poderiam ser colocadas vírgulas ou travessões, sem prejuízo gramatical, em reforço à semântica.","O verbo “contribuem” no plural se justifica por conta de seu sujeito (referente) ser composto.","No extrato “cultura do estudo”, a palavra “estudo” foi formada pelo processo de derivação regressiva.","A palavra “desmotivação” é formada pelo processo de prefixação e sufixação."],"correta":2,"explicacao":"Gabarito: <strong>O verbo “contribuem” no plural se justifica por conta de seu sujeito (referente) ser composto.</strong>.","banca":"Intelectus","ano":2025,"temas_relacionados":["formacaoPalavras"]},{"id":7982,"enunciado":"“Esses manifestantes passaram a ser lembrados como os ‘mártires de Chicago’. Em homenagem a eles, a partir de 1890 correntes ideológicas do movimento operário internacional e organizações sindicais passaram a comemorar em 1º de maio o Dia do Trabalho, realizando grandes manifestações em todo o mundo, exceto nos Estados Unidos”. Nesse segmento do texto há três ocorrências do vocábulo em. Assinale a opção que mostra uma afirmativa correta sobre essas ocorrências.","opcoes":["As duas primeiras ocorrências mostram valor de tempo.","As três ocorrências mostram valor semântico diferente.","As duas últimas ocorrências mostram o mesmo valor semântico.","A última ocorrência tem valor de “causa”.","A primeira ocorrência tem valor de explicação."],"correta":1,"explicacao":"Gabarito: <strong>As três ocorrências mostram valor semântico diferente.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["formacaoPalavras"]},{"id":18536,"enunciado":"A partícula \"se\", em \"tornando-se\" (.2), indica que o sujeito da oração correspondente é indeterminado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":28391,"enunciado":"Como já foi empregado o artigo em \"os anos\" (L.17), preservam-se as relações de sentido e a correção gramatical, resultando em linguagem mais objetiva e clara, se a partícula \"os\" for omitida em \"os levaram\" (L.18).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":133029,"enunciado":"Considerando palavras do texto, julgue os itens seguintes, com relação à estrutura e formação de palavras da língua portuguesa.\n\nNo processo de formação dos vocábulos “integração” (L.15), “impulsiona” (L.18), “indefectivelmente” (L.23) e “imprudências” (L.27), identifica-se o prefixo in-, que neles expressa a noção de mudança de estado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":133030,"enunciado":"Considerando palavras do texto, julgue os itens seguintes, com relação à estrutura e formação de palavras da língua portuguesa.\n\nO sufixo identificado na formação dos vocábulos “representantes” (L.4) e “emergentes” (L.5) expressa a noção de paciente das ações de representar e emergir, respectivamente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":133031,"enunciado":"Considerando palavras do texto, julgue os itens seguintes, com relação à estrutura e formação de palavras da língua portuguesa.\n\n\nTêm sentidos semelhantes o prefixo dos vocábulos “internacionalizados” (L.8) e “intertemporais” (L.19) e a preposição “entre” (L.25).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":420791,"enunciado":"Segundo o texto, entre as regras parlamentaristas que D. Pedro II consideraria inaceitáveis estavam as que visassem atribuir ao Poder Legislativo a prerrogativa de determinar a composição do gabinete ministerial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":420817,"enunciado":"No trecho “dissipam-se para latitudes mais baixas” (L.21), a partícula “se” tem função apassivadora.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":825800,"enunciado":"Considerando as ideias e os aspectos linguísticos desse texto, julgue o item a seguir.\n\nEstaria garantida a correção gramatical do texto se, no trecho “vem se multiplicando” (linha 8), a partícula “se” fosse deslocada para imediatamente depois da forma de gerúndio – vem multiplicando-se.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":872754,"enunciado":"Com relação à variação linguística, aos fatores de textualidade e aos aspectos linguísticos do texto 6A1BBB, julgue o item a seguir.\n\n\n\n\nEm “apesar de muitos o esquecerem” (ℓ . 8 e 9), a partícula “o” refere-se a “O homem” (ℓ .8).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":872787,"enunciado":"Considerando os aspectos linguísticos e os sentidos do texto 6A3BBB, julgue o item que se segue.\n\n\n\n\nEm “demandava-se” (ℓ.32) e “se veem pressionadas” (ℓ.34), a partícula “se” recebe classificações distintas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":872796,"enunciado":"Em relação às estruturas linguísticas e às ideias do texto 6A4AAA e aos múltiplos aspectos a ele relacionados, julgue o item seguinte.\n\n\n\n\nAs palavras “conspiração”, “sutilmente” e “terríveis” são formadas pelo processo morfológico de formação de palavras denominado sufixação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":1764792,"enunciado":"No que se refere ao texto e a seus aspectos linguísticos, julgue o item.\n\nNa forma verbal “Cogita-se” (linha 28), a partícula “se” indica que o sujeito da oração é indeterminado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":1913149,"enunciado":"Com relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nNa oração que inicia o texto, a partícula “se” indica que o sujeito é indeterminado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2077731,"enunciado":"Acerca do texto e de seus aspectos semânticos e linguísticos, julgue o item.\n\nEm relação à composição do gênero do texto, três elementos são obrigatórios: a tese, isto é, o ponto de vista a ser defendido; os argumentos, que sustentam a defesa temática; e a conclusão, que sintetiza e reforça o que foi exposto; tudo isso imerso em uma postura argumentativa-persuasiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2077735,"enunciado":"No que se refere aos aspectos de composição linguística e às classificações quanto ao gênero dos textos I, II e III, julgue o item.\n\nOs textos apresentam assuntos correlatos, mas estruturas distintas: o texto I é de natureza narrativa e descritiva; o texto II é uma campanha comunitária; e o texto III é uma citação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2077736,"enunciado":"No que se refere aos aspectos de composição linguística e às classificações quanto ao gênero dos textos I, II e III, julgue o item.\n\nOs textos utilizam apelo emocional e linguagem exclusivamente verbal, a fim de chamar a atenção para a importância de uma causa necessária para uma sociedade de direitos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2077739,"enunciado":"No que se refere aos aspectos de composição linguística e às classificações quanto ao gênero dos textos I, II e III, julgue o item.\n\nSe a frase central do texto II fosse reescrita da seguinte forma: Onde há pessoas, nós enxergamos cidadãos, seriam mantidas as relações sintáticas e semânticas da estrutura original.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2077740,"enunciado":"No que se refere aos aspectos de composição linguística e às classificações quanto ao gênero dos textos I, II e III, julgue o item.\n\nConsiderando as informações dos textos, é correto afirmar o seguinte: o Brasil possui muitos cidadãos em situação de vulnerabilidade social; a defensoria pública deve protegê-los; e o assistencialismo social surge como oportunismo nesse contexto nacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2205207,"enunciado":"Com base na estrutura e no conteúdo do texto, julgue o item.\n\n\n\n\nA expressão “conforme” (linha 18) possui o mesmo valor semântico de conquanto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":2520002,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item a seguir.\n\n\n\n\nNas linhas 8 e 9, as duas ocorrências da palavra “que” apresentam naturezas morfológicas distintas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":3046806,"enunciado":"Julgue o item a seguir.\n\nO uso do hífen para unir prefixos aos radicais das palavras, conforme as normas gramaticais estabelecidas pela língua portuguesa, continua a ser obrigatório mesmo após as alterações introduzidas pelo Acordo Ortográfico de 2009.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras","ortografia","hifen"]},{"id":3610459,"enunciado":"Quanto à estruturação linguística e gramatical do texto, julgue o item seguinte.\n\n\n\n\nNo trecho “da capacidade cardiorrespiratória”, a palavra “cardiorrespiratória” é formada pela junção do prefixo “cardio‑“, que significa “coração”, com o vocábulo “respiratório”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":3683376,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir.\n\n\n\n\nNo excerto “A relação entre terapeuta e paciente desenvolve‑se a partir do estabelecimento de micro‑objetivos definidos em conjunto, criando um ambiente de corresponsabilidade e estímulo que fortalece o processo terapêutico.”, os termos “micro‑objetivos” e “corresponsabilidade” seguem as mesmas regras para emprego ou não aplicação do hífen, pois possuem prefixos de mesma origem.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras","hifen"]},{"id":3683384,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir.\n\n\n\n\nNa passagem “Reconhecer a importância motivacional do fisioterapeuta, portanto, significa valorizar uma dimensão terapêutica que transcende os aspectos puramente físicos da reabilitação.”, o vocábulo “portanto” introduz uma oração coordenada conclusiva, que confere valor semântico de arremate da ideia defendida no texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]},{"id":4120681,"enunciado":"Julgue o seguinte item, referente às estruturas linguísticas e ao vocabulário empregados no texto CG7A1.\n\n\n\n\nNo trecho \"as alterações climáticas e o aquecimento global tornaram-se temas centrais nas pautas de diversas nações\" (primeiro parágrafo), o emprego da partícula \"se\" indica que o sujeito da oração se classifica como indeterminado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["formacaoPalavras"]}];
